int solution(int x, const int *a, int n) {
    char *remaining = calloc((size_t)x + 2, 1);
    int empty = x;
    for (int i = 1; i <= x; i++) {
        remaining[i] = 1;
    }
    for (int i = 0; i < n; i++) {
        if (a[i] >= 1 && a[i] <= x && remaining[a[i]]) {
            remaining[a[i]] = 0;
            empty--;
        }
        if (empty == 0) {
            free(remaining);
            return i;
        }
    }
    free(remaining);
    return -1;
}

static int find_min(const int *a, int len, int c) {
    int x = a[c];
    int position = c;
    while (c < len) {
        if (x > a[c]) {
            x = a[c];
            position = c;
        }
        c++;
    }
    return position;
}

