char *center(char *s, int size, char pad) {
    if (s == NULL || size <= (int)strlen(s)) {
        return s;
    }
    int len = (int)strlen(s);
    char *sb = (char *)malloc(size + 1);
    int pos = 0;
    for (int i = 0; i < (size - len) / 2; i++) {
        sb[pos++] = pad;
    }
    for (int i = 0; i < len; i++) {
        sb[pos++] = s[i];
    }
    while (pos < size) {
        sb[pos++] = pad;
    }
    sb[pos] = '\0';
    return sb;
}

