int solution(int X, const int *A, int len) {
    char *covered = calloc(X + 1, sizeof(char));
    int distinct = 0;
    for (int i = 0; i < len; i++) {
        int leaf = A[i];
        if (leaf >= 1 && leaf <= X && !covered[leaf]) {
            covered[leaf] = 1;
            distinct++;
        }
        if (distinct == X) {
            free(covered);
            return i;
        }
    }
    free(covered);
    return -1;
}

