#include <stdlib.h>

int solution(int X, const int *A, int len) {
    if (X > len) {
        return -1;
    }
    int *is_filled = calloc(X > 0 ? (size_t)X : 1, sizeof(int));
    int jumped = 0;
    for (int i = 0; i < len; i++) {
        int x = A[i];
        if (x <= X) {
            if (is_filled[x - 1] == 0) {
                is_filled[x - 1] = 1;
                jumped += 1;
                if (jumped == X) {
                    free(is_filled);
                    return i;
                }
            }
        }
    }
    free(is_filled);
