    if (length < 1) {
        return NULL;
    }
    char *buf = malloc((size_t)length + 1);
    size_t sym_len = strlen(symbols);
    for (int idx = 0; idx < length; ++idx) {
        buf[idx] = symbols[rand() % (int)sym_len];
    }
    buf[length] = '\0';
    shuffle(buf);
    return buf;
}

