int solution(int x, const int *a, int n) {
    char *seen = calloc((size_t)x + 1, 1);
    int distinct = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] >= 0 && a[i] <= x && !seen[a[i]]) {
            seen[a[i]] = 1;
            distinct++;
        }
        if (distinct == x) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

