const char *filter(const char *source, const char *dest, int dstart, int dend, int decimalDigits) {
    int dotPos = -1;
    int len = (int)strlen(dest);
    for (int i = 0; i < len; i++) {
        char c = dest[i];
        if (c == '.' || c == ',') {
