int is_anagram (const char *s1, const char *s2) {
    if (strlen (s1) != strlen (s2)) {
        return 0;
    }
    size_t n = strlen (s1);
    char *c1 = strdup (s1);
    char *c2 = strdup (s2);
    for (size_t i = 0; i < n; i++) {
        c1 [i] = (char) tolower ((unsigned char) c1 [i]);
        c2 [i] = (char) tolower ((unsigned char) c2 [i]);
    }
    qsort (c1, n, sizeof (char), cmp_char);
    qsort (c2, n, sizeof (char), cmp_char);
    int result = (memcmp (c1, c2, n) == 0);
    free (c1);
    free (c2);
    return result;
}

