int solution (int N) {
    int gap = 0;
    char binary_str [64];
    int idx = 0;
    unsigned int v = (unsigned int) N;
    if (v == 0) {
        binary_str [idx++] = '0';
    }
    while (v > 0) {
        binary_str [idx++] = (char) ('0' + (v % 2));
        v /= 2;
    }
    binary_str [idx] = '\0';
    for (int l = 0, r = idx - 1; l < r; l++, r--) {
        char t = binary_str [l];
        binary_str [l] = binary_str [r];
        binary_str [r] = t;
    }
    int current = 0;
    for (int i = 0; i <= idx; i++) {
        if (i < idx && binary_str [i] != '1') {
            current++;
        } else {
            if (current > gap) {
                gap = current;
            }
            current = 0;
        }
    }
    return gap;
}

