int solution(int X, const int *A, int size) {
    int *check = (int *)calloc((size_t)X, sizeof(int));
    int cmp = 0;
    int time = -1;
    for (int x = 0; x < size; x++) {
        int temp = A[x];
        if (temp <= X) {
            if (check[temp - 1] > 0) {
                continue;
            }
            check[temp - 1]++;
            cmp++;
        }
        if (cmp == X) {
            time = x;
            break;
        }
    }
    free(check);
    return time;
}

