int solution(int X, const int *A, int n) {
    int *present = calloc((size_t) X + 1, sizeof(int));
    int remaining = X;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 1 && A[i] <= X && present[A[i]]) {
            present[A[i]] = 0;
            remaining--;
        }
        if (remaining == 0) {
            free(present);
