static int matches_number(const char *s) {
    const char *p = s;
    if (*p == '+' || *p == '-') {
        p++;
    }
    const char *intDigits = p;
    while (*p >= '0' && *p <= '9') {
        p++;
    }
    size_t intLen = (size_t)(p - intDigits);
    if (*p == '.') {
        p++;
        const char *fracDigits = p;
        while (*p >= '0' && *p <= '9') {
            p++;
        }
        if (p == fracDigits && intLen == 0) {
            return 0;
        }
    } else if (intLen == 0) {
        return 0;
    }
    return *p == '\0';
}

