        emptyPosition[i] = 0;

    for(i = 0; i < N; i++)
    {
        if(emptyPosition[A[i] - 1] == 0)
            emptyPosition[A[i] - 1] = 1;
        if(allFilled(emptyPosition, X))
            return i;
    }

    return -1;
}

