    int *present = calloc((size_t) X + 2, sizeof(int));
    for (int v = 1; v <= X; v++) {
        present[v] = 1;
    }
    int remaining = X;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 1 && A[i] <= X && present[A[i]]) {
            present[A[i]] = 0;
            remaining--;
        }
        if (remaining == 0) {
            free(present);
            return i;
        }
    }
    free(present);
    return -1;
}

