int solution(int X, const int *A, int len) {
    char *seen = (char *)calloc((size_t)X + 1, 1);
    int sum1 = 0;
    int sum2 = 0;
    for (int i = 0; i <= X; i++) {
        sum1 += i;
    }
    for (int i = 0; i < len; i++) {
        int value = A[i];
        if (value >= 0 && value <= X && seen[value]) {
            continue;
        }
        if (value >= 0 && value <= X) {
            seen[value] = 1;
        }
        sum2 += value;
        if (sum1 == sum2) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

