struct Entry {
  int key;
  int value;
};

struct HashMap {
  int size;
  int capacity;
  struct Entry** table;
};

struct HashMap* createHashMap(int capacity) {
    struct HashMap* HashMap_object = (struct HashMap*) malloc (sizeof (struct HashMap));
    HashMap_object->capacity = capacity;
    HashMap_object->size = 0;
    HashMap_object->table = (struct Entry**) malloc (capacity * sizeof (struct Entry*));
    int i;
    for (i = 0; i < capacity; i++)
        HashMap_object->table[i] = NULL;
    return HashMap_object;
}

int get(struct HashMap* map, int key) {
    int index = key % map->capacity;
    struct Entry* current = map->table[index];
    while (current != NULL) {
        if (current->key == key)
            return current->value;
        current = current->next;
    }
    return -1;
}

void put(struct HashMap* map, int key, int value) {
    int index = key % map->capacity;
    struct Entry* new_entry = (struct Entry*) malloc (sizeof (struct Entry));
    new_entry->key = key;
    new_entry->value = value;
    new_entry->next = map->table[index];
    map->table[index] = new_entry;
    map->size++;
}


