int* sort (int* numbers, int digit) {
    if (numbers.length== 0 || digit <= 0) return numbers;
    int space[][1] = {0};
    int len[10] = {0};
    int i, j = 0;
    for (j = 0; j < numbers.length; j ++) {
        i = (numbers [j] / digit) % 10;
        len [i] ++;
        space [i] = putInBucket (space [i], numbers [j]);
    }
    for (i = 0; i < 10; i ++) {
        int* bucket = (int*)malloc(len [i] * sizeof(int));
        for (int k = 0;  k < len [i]; k ++) 
            bucket [k] = space [i] [k];
        space [i] = sort (bucket, digit / 10);
        free(bucket);
    }
    int k = 0;
    for (i = 0; i < 10; i ++) {
        for (j = 0; j < len [i]; j ++) {
            numbers [k] = space [i] [j];
            k ++;
        }
    }
    return numbers;
}

