int solution(int X, const int *A, int n) {
    if (X > n) return -1;
    int *is_filled = (int *) calloc(X, sizeof(int));
    int jumped = 0;
    for (int i = 0; i < n; i++) {
        int x = A[i];
        if (x <= X) {
            if (is_filled[x - 1] == 0) {
                is_filled[x - 1] = 1;
                jumped++;
                if (jumped == X) {
                    free(is_filled);
                    return i;
                }
            }
        }
    }
    free(is_filled);
    return -1;
}

