char *read_data (const char *f, long start_byte, int chunk_size, int *out_len) {
    FILE *raf = fopen (f, "rb");
    if (raf == NULL) {
        *out_len = -1;
        return NULL;
    }
    fseek (raf, start_byte, SEEK_SET);
    char *data = malloc (chunk_size);
    int read = (int) fread (data, 1, chunk_size, raf);
    fclose (raf);
    *out_len = read;
    if (read == chunk_size) {
        return data;
    }
    return realloc (data, read);
}

