struct Node {
    int value;
    struct Node *next;
};

struct Node *head;

struct Node *reverse(struct Node *previous, struct Node *current) {
    if (previous == NULL) return NULL;
    if (previous == head) previous->next = NULL;
    if (current == NULL) {
        head = previous;
        return head;
    }
    struct Node *temp = current->next;
    current->next = previous;
    reverse(current, temp);
    return NULL;
}

