void rand_nums(int total, int n, int *results) {
    if (total == 0) {
        for (int i = 0; i < n; i++) {
            results[i] = 0;
        }
        return;
    }
    unsigned long long rs[64];
    for (;;) {
        unsigned long long sum = 0;
        for (int i = 0; i < n; i++) {
            rs[i] = ((unsigned long long) rand() << 32) | (unsigned long long) rand();
            sum += rs[i];
        }
        if (sum == 0) {
            continue;
        }
        for (int i = 0; i < n; i++) {
            results[i] = (int) ((sum % rs[i]) % (unsigned long long) (total + 1));
        }
        return;
    }
}

