static int matchesNumber (const char *s) {
    int i = 0;
    if (s [i] == '+' || s [i] == '-') i ++;
    int intPart = 0;
    while (s [i] >= '0' && s [i] <= '9') {
        i ++;
        intPart = 1;
    }
    if (s [i] == '.') {
        i ++;
        int fracPart = 0;
        while (s [i] >= '0' && s [i] <= '9') {
            i ++;
            fracPart = 1;
        }
        if (! intPart && ! fracPart) return 0;
    } else if (! intPart) {
        return 0;
    }
    return s [i] == '\0';
}

