}

void decode_color(int color, int *r, int *g, int *b) {
    int mask = 0xFF;
    *r = (color & (mask << 16)) >> 16;
    *g = (color & (mask << 8)) >> 8;
    *b = (color & (mask << 0)) >> 0;
}

