typedef struct {
    int type;
    int age;
    char name[32];
}Animal;

int partition (Animal *ar, int low, int high) 
{ 
    int pivot = ar[high].age;
    int i = (low - 1);   
    int j;

    Animal temp;

    for (j = low; j <= high - 1; j++) 
    { 
        if (ar[j].age <= pivot) 
        { 
            i++;  
            temp = ar[i];
            ar[i] = ar[j];
            ar[j] = temp;
        } 
    } 
    temp = ar[i + 1];
    ar[i + 1] = ar[high];
    ar[high] = temp;
    return (i + 1); 
} 

void quickSort(Animal *ar, int low, int high) 
{ 
    if (low < high) 
    { 
        int pi = partition(ar, low, high); 

        quickSort(ar, low, pi - 1); 
        quickSort(ar, pi + 1, high); 
    } 
}

