int solution(int X, const int *A, int n) {
    static char present[MAX_VALUE + 1];
    memset(present, 0, sizeof(present));
    for (int v = 1; v <= X; v++) present[v] = 1;
    int remaining = X;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 1 && A[i] <= X && present[A[i]]) {
            present[A[i]] = 0;
            remaining--;
        }
        if (remaining == 0) return i;
    }
    return -1;
}

