char *decrypt(const char *s) {
    char *tmp = strdup(s);
    int ends_hash = s[strlen(s) - 1] == '#';
    int ngroups = 1;
    for (const char *p = s; *p; p++)
        if (*p == '#') ngroups++;
    char *buf = malloc(strlen(s) + 2);
    size_t n = 0;
    int i = 0;
    char *token = strtok(tmp, "#");
    while (token != NULL) {
        int len = (int)strlen(token);
        int j = 0;
        if (i == ngroups - 1 && !ends_hash) j = len;
        if (len > 2) j = len - 2;
        for (int k = 0; k < j; k++)
            buf[n++] = (char)('a' + (token[k] - '0') - 1);
        if (j < len)
            buf[n++] = (char)('a' + atoi(token + j) - 1);
        i++;
        token = strtok(NULL, "#");
    }
    buf[n] = '\0';
    free(tmp);
    return buf;
}

static int product_of_proper_divisors (int inputNumber) {
    int j = 1;
    int prod = 1;
    while (j < inputNumber) {
        if (inputNumber % j == 0) {
            prod *= j;
        }
        j++;
    }
    return prod;
}

