char *get_name (const char *value) {
    static char buffer [256];
    int number;
    buffer [0] = '\0';
    if (value [0] == '\0') {
        number = 0;
    } else if (strlen (value) > 4) {
        number = atoi (value + strlen (value) - 4);
    } else {
        number = atoi (value);
    }
    number %= 1000;
    if (number >= 100) {
        strcat (buffer, unit_name (number / 100));
        strcat (buffer, " ");
        strcat (buffer, scale_name (2));
    }
    const char *tname = tens_name (number % 100);
    if (tname [0] != '\0' && number >= 100) {
        strcat (buffer, " ");
    }
    strcat (buffer, tname);
    return buffer;
}

int solution(int X, const int *A, int n) {
    int *seen = calloc((size_t) X + 1, sizeof(int));
    int distinct = 0;
    int hasX = 0;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 1 && A[i] <= X && !seen[A[i]]) {
            seen[A[i]] = 1;
            distinct++;
            if (A[i] == X) hasX = 1;
        }
        if (hasX && distinct == X) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

