char *read_bytes (FILE *input_stream, int *out_len) {
    int capacity = 32 * 1024;
    int size = 0;
    char *buffer = malloc (capacity);
    int read;
    while ((read = (int) fread (buffer + size, 1, capacity - size, input_stream)) > 0) {
        size += read;
        if (size == capacity) {
            capacity *= 2;
            buffer = realloc (buffer, capacity);
        }
    }
    *out_len = size;
    return buffer;
}

