#include<stdlib.h>
#include<string.h>

char *decrypt(const char *s)
{
    const char delimiter = '#';
    char *groups[64];
    int group_no = 0;
    char *copy = (char*) malloc(strlen(s) + 1);

    if (copy == NULL)
    {
        perror("ERROR - no memory left");
        exit(EXIT_FAILURE);
    }
    strcpy(copy, s);
    int last_group_no = 0;
    groups[group_no] = (char*) strtok(copy, &delimiter);
    while (groups[group_no] != NULL)
    {
        group_no++;
        last_group_no = group_no;
        groups[group_no] = (char*) strtok(NULL, &delimiter);
    }
    if (s[strlen(copy)] != '#')
    {
        last_group_no--;
    }
    int crypt[strlen(s)];
    int j;
    int k = 0;
    for (int i = 0; i < last_group_no; i++)
    {
        j = 0;
        if (strlen(groups[i]) > 2)
            j = strlen(groups[i]) - 2;
        for (int l = 0; l < j; l++)
        {
            char *char_digit = calloc(2, sizeof(char));
            strncpy(char_digit, &groups[i][l], 1);
            crypt[k] = atoi(char_digit);
            k++;
            free(char_digit);
        }
        if (j < strlen(groups[i]))
        {
            char *char_digit = calloc(3, sizeof(char));
            strncpy(char_digit, groups[i] + j, 2);
            crypt[k] = atoi(char_digit);
            k++;
            free(char_digit);
        }
    }
    char *n = (char*) calloc(strlen(s) + 1, sizeof(char));
    int index = 0;
    for (int i = 0; i < sizeof(crypt) / sizeof(crypt[0]); i++)
    {
        char c = (char) (97 + crypt[i] - 1);
        n[index] = c;
        index++;
    }
    free(copy);
    return n;
}

