int solution(int X, const int *A, int len) {
    if (X > len) return -1;
    int *isFilled = calloc(X, sizeof(int));
    int jumped = 0;
    for (int i = 0; i < len; i++) {
        int x = A[i];
        if (x >= 1 && x <= X && isFilled[x - 1] == 0) {
            isFilled[x - 1] = 1;
            jumped += 1;
            if (jumped == X) {
                free(isFilled);
                return i;
            }
        }
    }
    free(isFilled);
    return -1;
}

