Key secondMaxKey (struct nodes *node) {
    struct node *first = node;
    struct node *second;
    struct node *max;
    struct node *max_2;
    int comparison;

    if (node->size < 2) {
        return NULL;
    }
    second = node->next;
    comparison = first->key.compareTo(second->key);
    if (comparison > 0) {
        max = first;
        max_2 = second;
    } else {
        max = second;
        max_2 = first;
    }
    while (second->next != NULL) {
        max = second->key.compareTo(max->key);
        if (max > 0) {
            max_2 = max;
            max = second;
        } else if (max > max_2->key && max < max->key) {
            max_2 = second;
        }
        second = second->next;
    }

    return max_2->key;
}

