        else if (isdigit (ch)) {
            int value = 0;
            while (isdigit ((unsigned char) s [i])) {
                value = value * 10 + (s [i] - '0');
                i++;
            }
            num [(*m)++] = value;
        }
        else {
            printf ("include invalid character (%c).\n", ch);
            return 0;
        }
    }
    return 1;
}

