bool isBalanced(const char *str) {
    bool result = false;
    char stack[256];
    int top = 0;
    size_t i;
    if (strlen(str) < 2) return false;
    for (i = 0; i < strlen(str); i++) {
        char ch = str[i];
        if (!isLeft(ch) && leftOf(ch) == '\0') continue;
        if (isLeft(ch)) {
            stack[top++] = ch;
        } else {
            if (top > 0 && stack[--top] == leftOf(ch)) {
                result = true;
            } else {
                return false;
            }
        }
    }
    if (top != 0) return false;
    return result;
}

