	zip_stream.opaque = Z_NULL;
	zip_stream.avail_in = 0;
	zip_stream.next_in = Z_NULL;
	deflateInit2(&zip_stream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 15, 8, Z_DEFAULT_STRATEGY);

    // set the file
