    zip_stream.avail_in = strlen(data_to_compress);

    //Deflate(struct stream_state *strm, int flush).
    deflate(&zip_stream, Z_FINISH);
    fwrite(buffer, 1, 1024 - zip_stream.avail_out, file_stream); 

    //close file stream
