typedef struct Node {
    int val;
    struct Node *next;
} Node;

Node *reverse(Node *n, Node *p) {
    if (n == NULL) return NULL;
    if (n->next == NULL) {
        n->next = p;
        return n;
    }
    Node *r = reverse(n->next, n);
    n->next = p;
    return r;
}

