#include <stdlib.h>

int solution(int X, const int *A, int len) {
    int *check = calloc(X, sizeof(int));
    int cmp = 0;
    int time = -1;
    for (int x = 0; x < len; x++) {
        int temp = A[x];
        if (temp <= X) {
            if (check[temp - 1] > 0) continue;
            check[temp - 1]++;
            cmp++;
        }
        if (cmp == X) { time = x; break; }
    }
    free(check);
    return time;
}

