bool isPermutation(char *str1, char *str2){
    int len1 = strlen(str1);
    int len2 = strlen(str2);

    if (len1 != len2) return false;

    qsort(str1, len1, sizeof(char), compare);
    qsort(str2, len2, sizeof(char), compare);

    for (int i = 0; i < len1; i++){
        if (str1[i] != str2[i])
            return false;
    }
    return true;
} 

