#include <math.h>
#include <stdlib.h>
#include <time.h>

int getRandomNumberBetween(float numberOne, float numberTwo, float *out) {
    if (numberOne == numberTwo) {
        return -1;
    }
    float rand = (float)rand() / (float)RAND_MAX;
    float highRange = numberOne > numberTwo ? numberOne : numberTwo;
    float lowRange = numberOne < numberTwo ? numberOne : numberTwo;
    float lowRand = (float)floor(rand - 1);
    float highRand = (float)ceil(rand + 1);
    *out = (highRange - lowRange) * ((rand - lowRand) / (highRand - lowRand)) + lowRange;
    return 0;
}

void rand_nums(int total, int n, int results[]) {
    unsigned long long rs[64];
    unsigned long long totalPlus1 = (unsigned long long) total + 1;
    if (total == 0) {
        for (int i = 0; i < n; i++) results[i] = 0;
        return;
    }
    while (1) {
        unsigned long long sum = 0;
        for (int i = 0; i < n; i++) {
            rs[i] = ((unsigned long long) rand() << 32) | rand();
            sum += rs[i];
        }
        if (sum == 0) continue;
        for (int i = 0; i < n; i++) {
            results[i] = (int) ((sum % rs[i]) % totalPlus1);
        }
        return;
    }
}

