char *join(char **objects, int count, const char *delimiter) {
    if (count == 0) {
        char *empty = malloc(1);
        empty[0] = '\0';
        return empty;
    }
    size_t total = 1;
    for (int i = 0; i < count; i++) {
        total += strlen(objects[i]);
        if (i < count - 1) {
            total += strlen(delimiter);
        }
    }
    char *ret = malloc(total);
    ret[0] = '\0';
    for (int i = 0; i < count; i++) {
        strcat(ret, objects[i]);
        if (i < count - 1) {
            strcat(ret, delimiter);
        }
    }
    return ret;
}

