static int char_cmp(const void *a, const void *b) {
    return *(const unsigned char *)a - *(const unsigned char *)b;
}

bool is_permutation(const char *str1, const char *str2) {
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);
    if (len1 != len2) return false;
    char *x = malloc(len1 + 1);
    char *y = malloc(len2 + 1);
    strcpy(x, str1);
    strcpy(y, str2);
    qsort(x, len1, sizeof(char), char_cmp);
    qsort(y, len2, sizeof(char), char_cmp);
    bool equal = memcmp(x, y, len1) == 0;
    free(x);
    free(y);
    return equal;
}

int isPermutation(const char *a, const char *b) {
    size_t lenA = strlen(a), lenB = strlen(b);
    if (lenA != lenB) return 0;
    char *bArray = strdup(b);
    int found = 0;
    for (size_t i = 0; i < lenA; i++) {
        for (size_t k = 0; k < lenB; k++) {
            if (a[i] == bArray[k]) {
                found++;
                bArray[k] = (char)0xFF;
                break;
            }
        }
    }
    free(bArray);
    return found == (int)lenA;
}

