char *center(const char *s, int size, char pad) {
    if (s == NULL || size <= (int)strlen(s)) {
        return (char *)s;
    }
    char *sb = malloc(size + 1);
    int pos = 0;
    for (int i = 0; i < (size - (int)strlen(s)) / 2; i++) {
        sb[pos++] = pad;
    }
    for (const char *p = s; *p; p++) {
        sb[pos++] = *p;
    }
    while (pos < size) {
        sb[pos++] = pad;
    }
    sb[pos] = '\0';
    return sb;
}

