int solution(int X, const int A[], int len) {
    int *pending = malloc(((size_t)X + 1) * sizeof(int));
    for (int i = 1; i <= X; i++) pending[i] = 1;
    int remaining = X;
    int time = -1;
    for (int i = 0; i < len; i++) {
        if (A[i] >= 1 && A[i] <= X && pending[A[i]]) {
            pending[A[i]] = 0;
            remaining--;
        }
        if (remaining == 0) {
            time = i;
            break;
        }
    }
    free(pending);
    return time;
}

