int secondMaxKey(Node *first, size_t size) {
    if (size < 2) return -1;
    Node *max = NULL, *max2 = NULL;
    Node *second = first->next;
    if (first->key > second->key) {
        max = first;
        max2 = second;
    } else {
        max = second;
        max2 = first;
    }
    for (Node *x = second->next; x != NULL; x = x->next) {
        if (x->key > max->key) {
            max2 = max;
            max = x;
        } else if (x->key > max2->key && x->key < max->key) {
            max2 = x;
        }
    }
    return max2->key;
}

