        high[0] = '\0';
        strcpy(low, value);
    } else {
        int index = (int) len - PART_DIVIDER;
        strncpy(high, value, index);
        high[index] = '\0';
        strcpy(low, value + index);
    }
    processor_get_name(high, name, sizeof(name));
    if (name[0] != '\0') {
        strcat(buffer, name);
        strcat(buffer, SEPARATOR);
        strcat(buffer, get_token());
        if (low[0] != '\0') {
            strcat(buffer, SEPARATOR);
        }
    }
    processor_get_name(low, name, sizeof(name));
    if (low[0] != '\0') {
        strcat(buffer, name);
    }
}

int solution(int X, const int *A, int n) {
    int *seen = calloc(X + 1, sizeof(int));
    int distinct = 0;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 0 && A[i] <= X && !seen[A[i]]) {
            seen[A[i]] = 1;
            distinct++;
        }
        if (distinct == X) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

