int solution(int x, const int *a, int len) {
    bool *removed = calloc(x + 2, sizeof(bool));
    int remaining = x;
    int i = 0;
    while (i < len) {
        int value = a[i];
        if (value >= 1 && value <= x && !removed[value]) {
            removed[value] = true;
            remaining--;
        }
        if (remaining == 0) {
            free(removed);
            return i;
        }
        i++;
    }
    free(removed);
    return -1;
}

