int solution(int n) {
    int gap = 0;
    char binary_str[33];
    int idx = 0;
    if (n == 0) {
        binary_str[idx++] = '0';
    }
    while (n > 0) {
        binary_str[idx++] = (char) ('0' + (n & 1));
        n >>= 1;
    }
    binary_str[idx] = '\0';
    for (int i = 0; i < idx / 2; i++) {
        char tmp = binary_str[i];
        binary_str[i] = binary_str[idx - 1 - i];
        binary_str[idx - 1 - i] = tmp;
    }
    printf("[");
    for (int i = 0; i < idx; i++) {
        if (binary_str[i] == '1') {
            printf(", ");
        }
    }
    printf("]\n");
    int start = 0;
    for (int i = 0; i <= idx; i++) {
        if (binary_str[i] == '1' || binary_str[i] == '\0') {
            int len = i - start;
            if (len > gap) {
                gap = len;
            }
            start = i + 1;
        }
    }
    return gap;
}

int find_combinations_count(int amount, const int *coins, int coinCount, int checkFromIndex) {
    if (amount == 0) {
        return 1;
    }
    if (amount < 0 || coinCount == checkFromIndex) {
        return 0;
    }
    int withFirst = find_combinations_count(amount - coins[checkFromIndex], coins, coinCount, checkFromIndex);
    int withoutFirst = find_combinations_count(amount, coins, coinCount, checkFromIndex + 1);
    return withFirst + withoutFirst;
}

