char *center(char *s, int size, char pad) {
  char *result;
  int left;
  int right;

  if( s == NULL || size <= strlen(s) ) 
    return s;

  result = malloc(size + 1);
  left = (size - strlen(s)) / 2;
  right = size - left;

  //Left Padding
  for(int i = 0; i < left; i++) {
    result[i] = pad;
  }
  // Output string
  strncpy(result + left, s, right);

  //Right Padding
  for( int i = right; i < size; i++) {
    result[i] = pad;
  }
  result[size] = '\0';

  return result;
}

