    const char *dot = strpbrk(dest, ".,");
    int dot_pos = (dot == NULL) ? -1 : (int)(dot - dest);
    if (dot_pos >= 0) {
        if (strcmp(source, ".") == 0 || strcmp(source, ",") == 0) {
            *result = "";
            return 1;
        }
        if (dend <= dot_pos) {
            *result = NULL;
            return 0;
