            inWord = false;
        } else {
            numLetters++;
            if (! inWord) {
                numWords++;
                inWord = true;
            }
        }
    }
    if (numWords > 0) {
        printf ("Average word length: %.1f (C = %d, N = %d)\n",
            (float) numLetters / numWords, numLetters, numWords);
    } else {
        printf ("You didn't enter any words\n");
    }
    return 0;
}

