int * randNums (int total, int n){
    int results[n];
    if (total == 0) {
        for (int i = 0; i < n; i++) 
            results[i] = 0;
        return results;
    }
    int rs[n];
    int totalPlus1 = total + 1;
    while (true) {
        for (int i = 0; i < n; i++) {
            // Generate a random integer in between 0 and 256.
            rs[i] = rand() % 256;
        }
        int sum = 0;
        for (int i = 0; i < n; i++) {
            sum += rs[i];
        }
        if (sum == 0)
            continue;
        for (int i = 0; i < n; i++) {

            results[i] = sum%rs[i]%totalPlus1;
        }
        return results;
    }
}

