int solution(int n) {
    char binary[33];
    int idx = 0;
    unsigned int value = (unsigned int) n;
    while (value > 0) {
        binary[idx++] = (char) ('0' + (value & 1u));
        value >>= 1;
    }
    binary[idx] = '\0';
    int gap = 0;
    int current = 0;
    for (int i = 0; i < idx; i++) {
        if (binary[i] == '1') {
            if (current > gap) gap = current;
            current = 0;
        } else {
            current++;
        }
    }
    if (current > gap) gap = current;
    return gap;
}

