int solution(int X, int A[]) {
    int size = sizeof(A)/sizeof(int);
    int check[X];
    memset(check, 0, X);
    int cmp = 0;
    int time = -1;
    for (int x = 0; x < size; x++) {
        int temp = A[x];
        if (temp <= X) {
            if (check[temp - 1] > 0) {
                continue;
            }
            check[temp - 1]++;
            cmp++;
        }
        if (cmp == X) {
            time = x;
            break;
        }
    }
    return time;
}

