char *join(char **input, int count, const char *delimiter) {
    size_t dlen = strlen(delimiter);
    size_t total = 1;
    for (int i = 0; i < count; i++) {
        total += strlen(input[i]) + dlen;
    }
    char *sb = (char *)malloc(total);
    sb[0] = '\0';
    for (int i = 0; i < count; i++) {
        strcat(sb, input[i]);
        strcat(sb, delimiter);
    }
    size_t length = strlen(sb);
    if (length > 0) {
        sb[length - dlen] = '\0';
    }
    return sb;
}

