int solution(int x, const int *a, int n) {
    int target = x * (x + 1) / 2;
    int sum = 0;
    int *seen = calloc(x + 1, sizeof(int));
    for (int i = 0; i < n; i++) {
        if (a[i] <= x && a[i] >= 0 && !seen[a[i]]) {
            seen[a[i]] = 1;
            sum += a[i];
            if (sum == target) {
                free(seen);
                return i;
            }
        }
    }
    free(seen);
    return -1;
}

