bool isAnagram(const char *s1, const char *s2)  
{  
    int n1 = strlen(s1); 
    int n2 = strlen(s2); 

    if (n1 != n2) 
        return false;

    char *low_s1 = malloc(n1 + 1);
    char *low_s2 = malloc(n2 + 1);

    for (int i = 0; i < n1; i++) 
    { 
        low_s1[i] = tolower(s1[i]); 
        low_s2[i] = tolower(s2[i]); 
    } 

    qsort(low_s1, n1, sizeof(char), compare); 
    qsort(low_s2, n2, sizeof(char), compare); 

    bool ret = (strcmp(low_s1, low_s2) == 0); 

    free(low_s1);
    free(low_s2);
    return ret; 
}

