int solution(int x, const int *a, int len) {
    int *seen = malloc(sizeof(int) * (x > 0 ? (size_t)x : 1));
    int count = 0;
    for (int i = 0; i < len; i++) {
        if (a[i] <= x) {
            bool found = false;
            for (int j = 0; j < count; j++) {
                if (seen[j] == a[i]) {
                    found = true;
                    break;
                }
            }
            if (!found) seen[count++] = a[i];
        }
        if (count == x) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

