int solution (int X, const int *A, int n) {
    int *array_list = malloc (n * sizeof (int));
    int array_list_len = 0;
    int total = 0;
    int sum_v = X * (X + 1) / 2;
    for (int iii = 0; iii < n; iii++) {
        if (A [iii] <= X) {
            int found = 0;
            for (int k = 0; k < array_list_len; k++) {
                if (array_list [k] == A [iii]) {
                    found = 1;
                    break;
                }
            }
            if (! found) {
                total += A [iii];
                if (total == sum_v) {
                    free (array_list);
                    return iii;
                }
                array_list [array_list_len++] = A [iii];
            }
        }
    }
    free (array_list);
    return -1;
}

