int solution(int X, const int *A, int len) {
    bool *filled = calloc(X > 0 ? (size_t)X : 1, sizeof(bool));
    int remaining = X;
    for (int i = 0; i < len; i++) {
        if (A[i] >= 1 && A[i] <= X && !filled[A[i] - 1]) {
            filled[A[i] - 1] = true;
            remaining--;
