        if (remaining == 0) {
            free(filled);
            return i;
        }
    }
    free(filled);
    return -1;
}

void shuffle_array(int *ar, int ar_len) {
    for (int i = ar_len - 1; i > 0; i--) {
        int index = rand() % (i + 1);
        int a = ar[index];
        ar[index] = ar[i];
        ar[i] = a;
    }
}

