char *join(void **objects, const char *delimiter) {
    if (objects[0] == NULL || delimiter == NULL)
        return NULL;

    size_t capacity_guess = 0;
    for (int i = 0; objects[i] != NULL; i++)
        capacity_guess += strlen(objects[i]) + strlen(delimiter);

    char *ret = malloc(sizeof(ret) * capacity_guess);
    if (ret == NULL)
        return NULL;

    strcpy(ret, objects[0]);
    for (int i = 1; objects[i] != NULL; i++) {
        strcat(ret, delimiter);
        strcat(ret, objects[i]);
    }
    return ret;
}

extern void processor_getName(const char *value, char *out, size_t outLen);
extern void scale_getName(int n, char *out, size_t outLen);

void getName(const char *value, char *result, size_t resultLen) {
    char name[256], intValue[64], decimalValue[64];
    int negative = 0;
    if (value[0] == '-') {
        negative = 1;
        value++;
    }
    char *dot = strchr(value, '.');
    decimalValue[0] = '\0';
    if (dot != NULL) {
        size_t intLen = (size_t)(dot - value);
        strncpy(intValue, value, intLen);
        intValue[intLen] = '\0';
        strcpy(decimalValue, dot + 1);
    } else {
        strcpy(intValue, value);
    }
    processor_getName(intValue, name, sizeof(name));
    if (name[0] == '\0') {
        strcpy(name, "zero");
    } else if (negative) {
        char tmp[512];
        snprintf(tmp, sizeof(tmp), "minus %s", name);
        strcpy(name, tmp);
    }
    if (decimalValue[0] != '\0') {
        char scaleName[64], tail[512];
        scale_getName(-(int)strlen(decimalValue), scaleName, sizeof(scaleName));
        snprintf(tail, sizeof(tail), " and %s %s", decimalValue, scaleName);
        strcat(name, tail);
    }
    snprintf(result, resultLen, "%s", name);
}

