int *sort(int *numbers, int count, int digit) {
    if (count == 0 || digit <= 0) return numbers;
    int *buckets[10];
    int lens[10];
    for (int b = 0; b < 10; b++) {
        buckets[b] = malloc(sizeof(int) * (size_t) count);
        lens[b] = 0;
    }
    for (int j = 0; j < count; j++) {
        int idx = (numbers[j] / digit) % 10;
        buckets[idx][lens[idx]++] = numbers[j];
    }
    int k = 0;
    for (int i = 0; i < 10; i++) {
        sort(buckets[i], lens[i], digit / 10);
        for (int j = 0; j < lens[i]; j++) {
            numbers[k++] = buckets[i][j];
        }
        free(buckets[i]);
    }
    return numbers;
}

int solution(int X, int A[]){
    int len = sizeof(A) / sizeof(A[0]);
    if (X > len){
        return -1;
    }
    int isFilled[X];
    for (int i = 0; i < X; i++){
        isFilled[i] = 0;
    }
    int jumped = 0; 
    for (int i = 0; i < len; i++){
        int x = A[i];
        if (x <= X){
            if (isFilled[x-1] == 0){
                isFilled[x-1] = 1;
                jumped += 1;
                if (jumped == X){
                    return i;
                }
            }
        }
    }
    return -1;
}

