#define N 5

static pthread_mutex_t lock_m = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t lock_c = PTHREAD_COND_INITIALIZER;
static int token = 0;

void run(int id) {
    pthread_mutex_lock(&lock_m);
    for (int i = 0; i < 5; i++) {
        while (token % N != id) pthread_cond_wait(&lock_c, &lock_m);
