char *center(const char *s, int size, char pad) {
    if (s == NULL || size <= (int)strlen(s)) return (char *)s;
    char *sb = malloc(size + 1);
    int left = (size - (int)strlen(s)) / 2;
    int pos = 0;
    for (int i = 0; i < left; i++) sb[pos++] = pad;
    for (int i = 0; s[i]; i++) sb[pos++] = s[i];
