#define ZERO_TOKEN "zero"
#define MINUS "minus"
#define SEPARATOR " "
#define UNION_AND " and "

char *get_name(const char *value) {
    char negative = 0;
    if (value[0] == '-') {
        negative = 1;
        value++;
    }
    const char *dot = strchr(value, '.');
    char *int_part = NULL;
    const char *decimal_part = NULL;
    if (dot != NULL) {
        size_t int_len = (size_t) (dot - value);
        int_part = malloc(int_len + 1);
        memcpy(int_part, value, int_len);
        int_part[int_len] = '\0';
        decimal_part = dot + 1;
        value = int_part;
    }
    const char *base = processor_get_name(value);
    char name[512];
    if (base[0] == '\0') {
        strcpy(name, ZERO_TOKEN);
    } else if (negative) {
        snprintf(name, sizeof(name), "%s%s%s", MINUS, SEPARATOR, base);
    } else {
        strcpy(name, base);
    }
    if (decimal_part != NULL && decimal_part[0] != '\0') {
        char tail[512];
        snprintf(tail, sizeof(tail), "%s%s%s%s", name, SEPARATOR, UNION_AND, processor_get_name(decimal_part));
        strcpy(name, tail);
    }
    free(int_part);
    return strdup(name);
}

int solution(int x) {
    int sum_v = x * (x + 1) / 2;
    int seen[1024];
    int seen_count = 0;
    for (int divisor = 1; divisor < x; divisor++) {
        if (x % divisor == 0) {
            int known = 0;
            for (int i = 0; i < seen_count; i++) {
                if (seen[i] == divisor) known = 1;
            }
            if (!known) {
                sum_v -= divisor;
                seen[seen_count++] = divisor;
            }
            if (divisor != x / divisor) {
                known = 0;
                for (int i = 0; i < seen_count; i++) {
                    if (seen[i] == x / divisor) known = 1;
                }
                if (!known) {
                    sum_v -= x / divisor;
                    seen[seen_count++] = x / divisor;
                }
            }
        }
    }
    return sum_v;
}

