    char type;
    char name[64];
    double value;
} Score;

int main(void) {
    const char *input = "(A,Name1,200), (A,Name1,200), (R,Name1,200), (A,Name2,900), (A,Name2,500)";
    Score scoreList[16];
    int count = 0;
    const char *p = input;
    while (*p) {
        char group[128];
        char *tokens[3];
        int g = 0, n = 0;
        char *tok;
        while (*p == ' ' || *p == ',') p++;
        if (*p != '(') break;
        p++;
        while (*p && *p != ')' && g < 127) group[g++] = *p++;
        group[g] = '\0';
        if (*p == ')') p++;
        tok = strtok(group, ",");
        while (tok != NULL && n < 3) {
            tokens[n++] = tok;
            tok = strtok(NULL, ",");
        }
        if (n == 3) {
            scoreList[count].type = tokens[0][0];
            strncpy(scoreList[count].name, tokens[1], sizeof(scoreList[count].name) - 1);
            scoreList[count].name[sizeof(scoreList[count].name) - 1] = '\0';
            scoreList[count].value = atof(tokens[2]);
            count++;
        }
    }
    (void)scoreList;
    return 0;
}

int solution(int X, int A[], int A_length)
{
    int *empty_positions = malloc(X * sizeof(int));
    int size = 0;

    // Create array of empty positions, of size X
    for (int i = 0; i < X; i++) {
        empty_positions[i] = i+1;
        size++;
    }

    // Iterate through array, A
    for (int i = 0; i < A_length; i++) {
        // Check if A[i] is in our empty_positions array
        for (int j = 0; j < size; j++) {
            // If it is, remove it from the array
            if (A[i] == empty_positions[j]) {
                empty_positions[j] = 0;
                size--;
            }
        }
        // Check if all positions are empty
        if (size == 0) {
            return i;
        }
    }
    return -1;
}

