int solution(int X, const int *A, int n) {
    int *inSet = malloc((X + 1) * sizeof(int));
    for (int v = 0; v <= X; v++) {
        inSet[v] = (v >= 1) ? 1 : 0;
    }
    int remaining = X;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 0 && A[i] <= X && inSet[A[i]]) {
            inSet[A[i]] = 0;
            remaining--;
        }
        if (remaining == 0) {
            free(inSet);
            return i;
        }
    }
    free(inSet);
    return -1;
}

