static int leaves_contains(const int *leaves, int n, int v) {
    for (int i = 0; i < n; i++) {
        if (leaves[i] == v) return 1;
    }
    return 0;
}

int solution(int x, const int *a, int len) {
    int leaves[1024];
    int n = 0;
    for (int i = 0; i < len; i++) {
        if (!leaves_contains(leaves, n, a[i])) {
            leaves[n++] = a[i];
        }
        if (leaves_contains(leaves, n, x) && n == x) {
            return i;
        }
    }
    return -1;
}

