#define SEPARATOR " "
#define EXPONENT 2
#define SCALE_NAME "hundred"

char *get_name(const char *value) {
    char *buffer = malloc(256);
    size_t vlen = strlen(value);
    int number;
    if (buffer == NULL) return NULL;
    buffer[0] = '\0';
    if (vlen == 0) {
        number = 0;
    } else if (vlen > 4) {
        number = atoi(value + vlen - 4);
    } else {
        number = atoi(value);
    }
    number %= 1000;
    if (number >= 100) {
        char tmp[16];
        sprintf(tmp, "%d", number / 100);
        strcat(buffer, unit_names[number / 100]);
        strcat(buffer, SEPARATOR);
        strcat(buffer, SCALE_NAME);
    }
    const char *tens_name = (number % 100) < 20 ? tens_names[number % 100] : "";
    if (tens_name[0] != '\0' && number >= 100) {
        strcat(buffer, SEPARATOR);
    }
    strcat(buffer, tens_name);
    return buffer;
}

void actionPerformed(ActionEvent e) {
   long duration = System.currentTimeMillis() - startTime;
   float progress = (float)duration / (float)RUN_TIME;
   linePoint = Point_Create();
   linePoint->x = getWidth()/2;
   if (progress < 0.5f) {
      linePoint->y = (int)roundf(getHeight() * (progress * 2));
   } else {
      if (progress > 1f) {
         progress = 1f;
         Timer_Stop(e->getSource());
         Point_Release(&linePoint);
         ballPoint = NULL;
      } else {
         linePoint->y = (int)roundf(getHeight() * (progress * 2));
         linePoint->y = getHeight() - (linePoint->y - getHeight());
         ballPoint->y = linePoint->y;
      }
   }
   repaint();
}

