const char *getProtocol(const char *uri) {
    const char *sep = (uri != NULL) ? strstr(uri, "://") : NULL;
    if (sep == NULL) {
        return "unknown";
    }
    static char protocol[16];
    size_t n = (size_t)(sep - uri);
    if (n >= sizeof protocol) {
        return "unknown";
    }
    memcpy(protocol, uri, n);
    protocol[n] = '\0';
    return protocol;
}

