char *remove_duplicates(const char *s) {
    size_t len = strlen(s);
    char *no_dupes = malloc(len + 1);
    size_t pos = 0;
    char seen[256] = { 0 };
    for (size_t i = 0; i < len; i++) {
        unsigned char ch = (unsigned char) s[i];
        if (!seen[ch]) {
            seen[ch] = 1;
            no_dupes[pos++] = s[i];
        }
    }
    no_dupes[pos] = '\0';
    return no_dupes;
}

