int solution(int x, const int *a, int n) {
    int *present = calloc((size_t)x + 1, sizeof(int));
    int left = x;
    for (int v = 1; v <= x; v++) {
        present[v] = 1;
    }
    for (int i = 0; i < n; i++) {
        if (a[i] >= 1 && a[i] <= x && present[a[i]] == 1) {
            present[a[i]] = 0;
            left--;
        }
        if (left == 0) {
            free(present);
            return i;
        }
    }
    free(present);
    return -1;
}

