#include <stddef.h>
#include <string.h>

const char *filter_input(const char *source, const char *dest, int dstart, int dend, int decimal_digits) {
    const char *dot = strchr(dest, '.');
    if (dot == NULL) dot = strchr(dest, ',');
    if (dot != NULL) {
        int dot_pos = (int)(dot - dest);
        if (strcmp(source, ".") == 0 || strcmp(source, ",") == 0) {
            return "";
        }
        if (dend <= dot_pos) {
            return NULL;
        }
        if ((int)strlen(dest) - dot_pos > decimal_digits) {
            return "";
        }
    }
    return NULL;
}

#include <string.h>

int decimalDigits = 2;

char *filter(const char *source, int start, int end, const char *dest, int dstart, int dend) {
    int dotPos = -1;
    int len = (int)strlen(dest);
    const char *p = dest;
    while (*p) {
        if (*p == '.' || *p == ',') {
            dotPos = (int)(p - dest);
            break;
        }
        p++;
    }
    if (dotPos >= 0) {
        if (strcmp(source, ".") == 0 || strcmp(source, ",") == 0) return "";
        if (dend <= dotPos) return NULL;
        if (len - dotPos > decimalDigits) return "";
    }
