int isPrime(int number) {
    if (number < 2) return 0;
    if (number == 2) return 1;
    if (number % 2 == 0) return 0;
    int i = 3;
    while (i * i <= number) {
        if (number % i == 0) return 0;
        i += 2;
    }
    return 1;
}

