int solution(int n) {
    char binary[65];
    char tmp[65];
    int t = 0;
    unsigned int v = (unsigned int) n;
    if (v == 0) {
        binary[0] = '0';
        binary[1] = '\0';
    } else {
        while (v > 0) {
            tmp[t++] = (char) ('0' + (v & 1));
            v >>= 1;
        }
        int pos = 0;
        while (t > 0) {
            binary[pos++] = tmp[--t];
        }
        binary[pos] = '\0';
    }
    int len = (int) strlen(binary);
    char *zero_arrays[65];
    int count = 0;
    int gap = 0;
    int start = 0;
    for (int i = 0; i <= len; i++) {
        if (i == len || binary[i] == '1') {
            zero_arrays[count] = (char *) malloc((size_t) (i - start) + 1);
            memcpy(zero_arrays[count], binary + start, (size_t) (i - start));
            zero_arrays[count][i - start] = '\0';
            if (i - start > gap) gap = i - start;
            start = i + 1;
            count++;
        }
    }
    printf("[");
    for (int i = 0; i < count; i++) {
        printf("%s%s", i > 0 ? ", " : "", zero_arrays[i]);
    }
    printf("]\n");
    return gap;
}

