} Node;

typedef struct {
    Node *head;
} List;

Node *list_reverse(List *list, Node *previous, Node *current) {
    if (previous == NULL) return NULL;
    if (previous == list->head) previous->next = NULL;
    if (current == NULL) {
        list->head = previous;
        return list->head;
    }
    Node *temp = current->next;
    current->next = previous;
    list_reverse(list, current, temp);
    return NULL;
}

