static int compare_chars(const void *a, const void *b) {
    return (int) (unsigned char) *(const char *) a - (int) (unsigned char) *(const char *) b;
}

int is_permutation(const char *str1, const char *str2) {
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);
    if (len1 != len2) return 0;
    char *x = malloc(len1 + 1);
    char *y = malloc(len2 + 1);
    strcpy(x, str1);
    strcpy(y, str2);
    qsort(x, len1, 1, compare_chars);
    qsort(y, len2, 1, compare_chars);
    int result = strcmp(x, y) == 0;
    free(x);
    free(y);
    return result;
}

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

static char left_of(char ch) {
    switch (ch) {
        case ')': return '(';
        case ']': return '[';
        case '}': return '{';
        default: return '\0';
    }
}

static bool is_left(char ch) {
    return ch == '(' || ch == '[' || ch == '{';
}

static bool is_right(char ch) {
    return ch == ')' || ch == ']' || ch == '}';
}

bool is_balanced(const char *str) {
    bool result = false;
    size_t len = strlen(str);
    if (len < 2) return false;
    char *stack = malloc(len + 1);
    size_t top = 0;
    for (size_t i = 0; i < len; i++) {
        char ch = str[i];
        if (!is_right(ch) && !is_left(ch)) continue;
        if (is_left(ch)) {
            stack[top++] = ch;
        } else {
            if (top > 0 && stack[--top] == left_of(ch)) {
                result = true;
            } else {
                free(stack);
                return false;
            }
        }
    }
    if (top != 0) result = false;
    free(stack);
    return result;
}

