int solution(int X, const int *A, int n) {
    char *leaves = calloc(X + 1, 1);
    int distinct = 0;
    int seenX = 0;
    for (int i = 0; i < n; i++) {
        int v = A[i];
        if (v >= 0 && v <= X) {
            if (!leaves[v]) {
                leaves[v] = 1;
                distinct++;
            }
            if (v == X) seenX = 1;
        }
        if (seenX && distinct == X) {
            free(leaves);
            return i;
        }
    }
    free(leaves);
    return -1;
}

