int *solution (const char *S, const int *P, const int *Q, int p_len) {
    int n = (int) strlen (S);
    int *answer = calloc (p_len, sizeof (int));
    int (*cumulative_answers) [n + 1] = calloc (4 * (n + 1), sizeof (int));
    for (int iii = 0; iii < n; iii++) {
        if (iii > 0) {
            for (int zzz = 0; zzz < 4; zzz++) {
                cumulative_answers [zzz] [iii + 1] = cumulative_answers [zzz] [iii];
            }
        }
        switch (S [iii]) {
            case 'A': cumulative_answers [0] [iii + 1] ++; break;
            case 'C': cumulative_answers [1] [iii + 1] ++; break;
            case 'G': cumulative_answers [2] [iii + 1] ++; break;
            case 'T': cumulative_answers [3] [iii + 1] ++; break;
        }
    }
    for (int iii = 0; iii < p_len; iii++) {
        for (int zzz = 0; zzz < 4; zzz++) {
            if ((cumulative_answers [zzz] [Q [iii] + 1] - cumulative_answers [zzz] [P [iii]]) > 0) {
                answer [iii] = zzz + 1;
                break;
            }
        }
    }
    free (cumulative_answers);
    return answer;
}

