    long sum1 = 0, sum2 = 0;
    for (int i = 0; i <= X; i++) sum1 += i;
    for (int i = 0; i < n; i++) {
        bool dup = false;
        for (int j = 0; j < seenCount; j++) {
            if (seen[j] == A[i]) { dup = true; break; }
