protected override void CalculateBiQuadCoefficients() {
    double k = Math.Tan(Math.PI * Frequency / SampleRate);
    double kk = k * k;
    double norm = 1 / (1 + k / Q + kk);
    double gain = 2 * norm;
    A0 = (1 + kk) * norm;
    A1 = (kk - 1) * gain;
    A2 = A0;
    B1 = A1;
    B2 = (1 - (k / Q) + kk) * norm;
}

