public class NameBuilder
{
    private const string Separator = " ";

    protected virtual int GetPartDivider()
    {
        return 3;
    }

    protected virtual string GetToken()
    {
        return "hundred";
    }

    protected virtual string ProcessName(string value)
    {
        return value;
    }

    public string GetName(string value)
    {
        StringBuilder buffer = new StringBuilder();
        string high, low;
        if (value.Length < GetPartDivider())
        {
            high = "";
            low = value;
        }
        else
        {
            int index = value.Length - GetPartDivider();
            high = value.Substring(0, index);
            low = value.Substring(index);
        }
        string highName = ProcessName(high);
        string lowName = ProcessName(low);
        if (!"".Equals(highName))
        {
            buffer.Append(highName);
            buffer.Append(Separator);
            buffer.Append(GetToken());
            if (!"".Equals(lowName))
            {
                buffer.Append(Separator);
            }
        }
        if (!"".Equals(lowName))
        {
            buffer.Append(lowName);
        }
        return buffer.ToString();
    }
}

public int Solution(int X, int[] A)
{
    int[] check = new int[X];
    int cmp = 0;
    int time = -1;
    for (int x = 0; x < A.Length; x++)
    {
        int temp = A[x];
        if (temp <= X)
        {
            if (check[temp - 1] > 0) continue;
            check[temp - 1]++;
            cmp++;
        }
        if (cmp == X)
        {
            time = x;
            break;
        }
    }
    return time;
}

