public int Solution(int X, int[] A) {
    if (X > A.Length) return -1;
    var isFilled = new bool[X];
    int jumped = 0;
    for (int i = 0; i < A.Length; i++) {
        int x = A[i];
        if (x <= X && !isFilled[x - 1]) {
            isFilled[x - 1] = true;
            jumped++;
            if (jumped == X) return i;
        }
    }
    return -1;
}

public static IList ToAnonymousList (this IEnumerable enumerable) {
    var enumerator = enumerable.GetEnumerator ();
    if (! enumerator.MoveNext ())
        throw new Exception ("?? No elements??");
    var value = enumerator.Current;
    var returnList = (IList) typeof (List < >).MakeGenericType (value.GetType ()).GetConstructor (Type.EmptyTypes).Invoke (null);
    returnList.Add (value);
    while (enumerator.MoveNext ())
        returnList.Add (enumerator.Current);
    return returnList;
}

public static string Center(string s, int size, char pad) {
    if (s == null || size <= s.Length) return s;
    var sb = new System.Text.StringBuilder(size);
    for (int i = 0; i < (size - s.Length) / 2; i++) {
        sb.Append(pad);
    }
    sb.Append(s);
    while (sb.Length < size) {
        sb.Append(pad);
    }
    return sb.ToString();
