public class DecimalFilter
{
    public int DecimalDigits;

    public string Filter(string source, int start, int end, string dest, int dstart, int dend)
    {
        int dotPos = -1;
        int len = dest.Length;
        for (int i = 0; i < len; i++)
        {
            char c = dest[i];
            if (c == '.' || c == ',')
            {
                dotPos = i;
                break;
            }
        }
        if (dotPos >= 0)
        {
            if (source == "." || source == ",")
            {
                return "";
            }
            if (dend <= dotPos)
            {
                return null;
            }
            if (len - dotPos > DecimalDigits)
            {
                return "";
            }
        }
        return null;
    }
}

