public static class SumFinder
{
    public static int Solution(int x, int[] a)
    {
        HashSet<int> set = new HashSet<int>();
        int sum1 = 0, sum2 = 0;
        for (int i = 0; i <= x; i++)
        {
            sum1 += i;
        }
        for (int i = 0; i < a.Length; i++)
        {
            if (set.Contains(a[i]))
            {
                continue;
            }
