public class Solution
{
    public int solution(int X, int[] A)
    {
        int len = A.Length;
        if (X > len)
        {
            return -1;
        }
        int[] isFilled = new int[X];
        int jumped = 0;
        for (int i = 0; i < len; i++)
        {
            int x = A[i];
            if (x <= X && isFilled[x - 1] == 0)
            {
                isFilled[x - 1] = 1;
                jumped += 1;
                if (jumped == X)
                {
                    return i;
                }
            }
        }
        return -1;
    }
}

