{
    if (Size() < 2)
    {
        return null;
    }
    Node max = null;
    Node max2 = null;
    Node second = first.next;
    if (first.key.CompareTo(second.key) > 0)
    {
        max = first;
        max2 = second;
    }
    else
    {
        max = second;
        max2 = first;
    }
    for (Node x = second.next; x != null; x = x.next)
    {
        if (x.key.CompareTo(max.key) > 0)
        {
            max2 = max;
