        {
            max2 = x;
        }
    }
    return max2;
}

public class FilterCoefficientsDistributed
{
    private double k;
    private double A0, A1, A2, B1, B2;

    public FilterCoefficientsDistributed(double sampleRatio)
    {
        k = sampleRatio;
        double norm = 1.0 / (1 + k / Q + k * k);
        A0 = norm + k * k * norm;
        A1 = 2 * k * k * norm - 2 * norm;
        A2 = A0;
        B1 = A1;
        B2 = norm - (k / Q) * norm + k * k * norm;
    }

    private const double Q = 1.0;
}

public IDisposable Enter (string key) {
    Locker locker = GetOrCreateLocker (key);
    locker.Enter ();
    locker.WaitCount --;
    return locker;
}

private Locker GetOrCreateLocker (string key) {
    lock (this.globalLock)
    {
        Locker existing;
        if (this.locks.TryGetValue (key, out existing)) {
            existing.WaitCount ++;
            return existing;
        }
        Locker created = new Locker (this, key);
        this.locks [key] = created;
        created.WaitCount ++;
        return created;
    }
}

