public class DecimalFilter
{
    private int decimalDigits = 2;

    public string Filter(string source, int start, int end, string dest, int dstart, int dend)
    {
        int dotPos = -1;
        int len = dest.Length;
        for (int i = 0; i < len; i++)
        {
            char c = dest[i];
            if (c == '.' || c == ',')
            {
                dotPos = i;
                break;
            }
        }
        if (dotPos >= 0)
        {
            if (source == "." || source == ",") return "";
            if (dend <= dotPos) return null;
            if (len - dotPos > decimalDigits) return "";
        }
        return null;
    }
}

public static class LeafTimes
{
    public static int Solution(int X, int[] A)
    {
        int size = A.Length;
        int[] check = new int[X];
        int cmp = 0;
        int time = -1;
        for (int x = 0; x < size; x++)
        {
            int temp = A[x];
            if (temp <= X)
            {
                if (check[temp - 1] > 0)
                {
                    continue;
                }
                check[temp - 1]++;
                cmp++;
            }
            if (cmp == X)
            {
                time = x;
                break;
            }
        }
        return time;
    }
}

