public static int [] solution(string s, int [] p, int [] q)
{
    int [] answer = new int [p.Length];

    int [] [] cumulativeAnswers = new int [4] [s.Length + 1];
    for (int i = 0; i < s.Length; i++)
    {
        if (i > 0)
        {
            for (int j = 0; j < 4; j++)
            {
                cumulativeAnswers[j][i + 1] = cumulativeAnswers [j][i];
            }
        }
        switch (s [i])
        {
            case 'A': 
                cumulativeAnswers[0][i + 1]++;
                break;
            case 'C': 
                cumulativeAnswers[1][i + 1]++;
                break;
            case 'G': 
                cumulativeAnswers[2][i + 1]++;
                break;
            case 'T': 
                cumulativeAnswers[3][i + 1]++;
                break;
        }
    }

    for (int i = 0; i < p.Length; i++)
    {
        for (int j = 0; j < 4; j++)
        {
            if ((cumulativeAnswers [j][q[i] + 1] - cumulativeAnswers[j][p[i]]) > 0)
            {
                answer[i] = j + 1;
                break;
            }
        }
    }

    return answer;
}

using System;
