internal static string GetIPAddress (HttpRequestBase request) {
    string forwarded = request.Headers ["Forwarded"];
    if (! String.IsNullOrEmpty (forwarded)) {
        foreach (string segment in forwarded.Split (',') [0].Split (';')) {
            string [] pair = segment.Trim ().Split ('=');
            if (pair.Length == 2 && pair [0].Equals ("for", StringComparison.OrdinalIgnoreCase)) {
                string ip = pair [1].Trim ('"');
                int left = ip.IndexOf ('[');
                if (left == 0) {
                    int right = ip.IndexOf (']');
                    ip = ip.Substring (1, right - 1);
                } else {
                    int colon = ip.IndexOf (':');
                    if (colon != - 1) {
                        ip = ip.Substring (0, colon);
                    }
                }
                return ip;
            }
        }
    }
    string xForwardedFor = request.Headers ["X-Forwarded-For"];
    if (! String.IsNullOrEmpty (xForwardedFor)) {
        return xForwardedFor.Split (',') [0];
    }
    return request.UserHostAddress;
}

public static string Decrypt (string s) {
    var crypt = new List<int> ();
    var groups = s.Split ('#');
    for (int i = 0; i < groups.Length; i++) {
        var group = groups [i];
        int j = 0;
        if ((i == (groups.Length - 1)) && !s.EndsWith ("#")) {
            j = group.Length;
        }
        if (group.Length > 2) {
            j = group.Length - 2;
        }
        for (int k = 0; k < j; k++) {
            crypt.Add (int.Parse (group.Substring (k, 1)));
        }
        if (j < group.Length) {
            crypt.Add (int.Parse (group.Substring (j, group.Length - j)));
        }
    }
    var n = new StringBuilder (crypt.Count);
    foreach (int c in crypt) {
        char d = (char) (('a' + c) - 1);
        n.Append (d);
    }
    return n.ToString ();
}

