public static string Filter(string source, string dest, int dstart, int dend, int decimalDigits)
{
    int dotPos = -1;
    for (int i = 0; i < dest.Length; i++)
    {
        char c = dest[i];
        if (c == '.' || c == ',')
        {
            dotPos = i;
            break;
        }
    }
    if (dotPos >= 0)
    {
        if (source == "." || source == ",")
        {
            return "";
        }
        if (dend <= dotPos)
        {
            return null;
        }
        if (dest.Length - dotPos > decimalDigits)
        {
            return "";
        }
    }
    return null;
}

