public static class Program
{
    private static int _outputCount;

    public static void Main()
    {
        var expensiveObjects = new ConcurrentQueue<object>();
        for (int i = 0; i < 4; i++)
        {
            expensiveObjects.Enqueue(new object());
        }
        Action drain = () =>
        {
            while (expensiveObjects.TryDequeue(out _))
            {
                Interlocked.Increment(ref _outputCount);
            }
        };
        Task[] tasks = new Task[4];
        for (int i = 0; i < 4; i++)
        {
            tasks[i] = Task.Run(drain);
        }
        Task.WaitAll(tasks, TimeSpan.FromSeconds(5));
        Console.WriteLine("Final: " + _outputCount);
    }
}

public static Double Correlation (Double [] Xs, Double [] Ys) {
    int n = Math.Min (Xs.Length, Ys.Length);
    Double avgX = Xs.Take (n).Average ();
    Double avgY = Ys.Take (n).Average ();
    Double sumX2 = 0, sumY2 = 0, sumXY = 0;
    for (int i = 0; i < n; ++ i) {
        sumX2 += Xs [i] * Xs [i];
        sumY2 += Ys [i] * Ys [i];
        sumXY += Xs [i] * Ys [i];
    }
    Double stdX = Math.Sqrt (sumX2 - n * avgX * avgX);
    Double stdY = Math.Sqrt (sumY2 - n * avgY * avgY);
    Double covariance = (sumXY - n * avgX * avgY);
    return covariance / stdX / stdY;
}

