public int[] ZeroFront(int[] nums) {
    if (nums == null) return null;
    int[] result = new int[nums.Length];
    int zeroesPos = 0;
    int othersPos = result.Length - 1;
    foreach (int value in nums) {
        if (value == 0) {
            result[zeroesPos++] = 0;
        } else {
            result[othersPos--] = value;
        }
    }
    return result;
}

