    {
        for (int i = 0; i < 4; i++) expensiveObjects.Enqueue(new object());
        List<Thread> workers = new List<Thread>();
        for (int i = 0; i < 4; i++)
        {
            Thread t = new Thread(MyRunnable);
            workers.Add(t);
            t.Start();
        }
        foreach (Thread t in workers) t.Join(5000);
        Console.WriteLine("Final: " + outputCount);
    }
}

