            max2 = second;
        }
        else
        {
            max = second;
            max2 = first;
        }
        for (Node x = second.Next; x != null; x = x.Next)
        {
            if (x.Key.CompareTo(max.Key) > 0)
            {
                max2 = max;
                max = x;
            }
            else if (x.Key.CompareTo(max2.Key) > 0 && x.Key.CompareTo(max.Key) < 0)
            {
                max2 = x;
            }
        }
        return max2.Key;
    }
}

