private static string Decrypt(string s)
{
  List<int> crypt = new List<int>();
  string[] groups = s.Split('#');
  for (int i = 0; i < groups.Length; i++)
  {
    string group = groups[i];
    int j = 0;
    if ((i == groups.Length - 1) && !s.EndsWith("#"))
    {
      j = group.Length;
    }
    if (group.Length > 2)
    {
      j = group.Length - 2;
    }
    for (int k = 0; k < j; k++)
    {
      crypt.Add(int.Parse(group.Substring(k, 1)));
    }
    if (j < group.Length)
    {
      crypt.Add(int.Parse(group.Substring(j, group.Length - j)));
    }
  }
  StringBuilder n = new StringBuilder(crypt.Count);
  foreach (int c in crypt)
  {
    char d = (char)(('a' + c) - 1);
    n.Append(d);
  }
  return n.ToString();
}

public static int[] Sort(int[] numbers, int digit)
{
    if (numbers.Length == 0 || digit <= 0)
        return numbers;

    int[][] space = new int[10][];
    int[] len = new int[10];
    int i, j = 0;
    for (j = 0; j < numbers.Length; j++)
    {
        i = (numbers[j] / digit) % 10;
        len[i]++;
        space[i] = PutInBucket(space[i], numbers[j]);
    }
    for (i = 0; i < 10; i++)
    {
        int[] bucket = new int[len[i]];
        for (int k = 0;
            k < len[i]; k++)
            bucket[k] = space[i][k];
        space[i] = Sort(bucket, digit / 10);
    }
    int k = 0;
    for (i = 0; i < 10; i++)
    {
        for (j = 0; j < len[i]; j++)
        {
            numbers[k] = space[i][j];
            k++;
        }
    }
    return numbers;
}

public static int[] Solution(string s, int[] p, int[] q)
{
    int[] answer = new int[p.Length];
    char[] chars = s.ToCharArray();
    int[][] cumulativeAnswers = new int[4][];
    for (int i = 0; i < 4; i++)
    {
        cumulativeAnswers[i] = new int[chars.Length + 1];
    }
    for (int iii = 0; iii < chars.Length; iii++)
    {
        if (iii > 0)
        {
            for (int zzz = 0; zzz < 4; zzz++)
            {
                cumulativeAnswers[zzz][iii + 1] = cumulativeAnswers[zzz][iii];
            }
        }
        switch (chars[iii])
        {
            case 'A': cumulativeAnswers[0][iii + 1]++; break;
            case 'C': cumulativeAnswers[1][iii + 1]++; break;
            case 'G': cumulativeAnswers[2][iii + 1]++; break;
            case 'T': cumulativeAnswers[3][iii + 1]++; break;
        }
    }
    for (int iii = 0; iii < p.Length; iii++)
    {
        for (int zzz = 0; zzz < 4; zzz++)
        {
            if ((cumulativeAnswers[zzz][q[iii] + 1] - cumulativeAnswers[zzz][p[iii]]) > 0)
            {
                answer[iii] = zzz + 1;
                break;
            }
        }
    }
    return answer;
}

