public static List<List<T>> GetPermutations<T>(IEnumerable<IEnumerable<T>> lists)
{
    var result = new List<List<T>>();
    List<IEnumerator<T>> iterators = new List<IEnumerator<T>>();
    foreach (var list in lists)
    {
        var it = list.GetEnumerator();
        if (it.MoveNext())
        {
            iterators.Add(it);
        }
    }
    if (iterators.Count == 0)
    {
        return result;
    }
    bool done = false;
    while (!done)
    {
        var current = new List<T>();
        foreach (var it in iterators)
        {
            current.Add(it.Current);
        }
        result.Add(current);
        var mainIt = iterators.GetEnumerator();
        mainIt.MoveNext();
        bool recurse;
        do
        {
            recurse = false;
            var subIt = mainIt.Current;
            if (!subIt.MoveNext())
            {
                subIt.Reset();
                subIt.MoveNext();
                if (!mainIt.MoveNext())
                {
                    done = true;
                }
                else
                {
                    recurse = true;
                }
            }
        } while (recurse);
    }
    return result;
}

