internal static string GetIPAddress (HttpRequestBase request) {
    string fromForwarded = ParseForwardedHeader (request);
    if (fromForwarded != null) {
        return fromForwarded;
    }
    string xForwardedFor = request.Headers ["X-Forwarded-For"];
    if (! String.IsNullOrEmpty (xForwardedFor)) {
        return xForwardedFor.Split (',') [0];
    }
    return request.UserHostAddress;
}

private static string ParseForwardedHeader (HttpRequestBase request) {
    string forwarded = request.Headers ["Forwarded"];
    if (String.IsNullOrEmpty (forwarded)) {
        return null;
    }
    foreach (string segment in forwarded.Split (',') [0].Split (';')) {
        string [] pair = segment.Trim ().Split ('=');
        if (pair.Length == 2 && pair [0].Equals ("for", StringComparison.OrdinalIgnoreCase)) {
            return StripEndpointSuffix (pair [1].Trim ('"'));
        }
    }
    return null;
}

private static string StripEndpointSuffix (string ip) {
    int left = ip.IndexOf ('[');
    if (left == 0) {
        int right = ip.IndexOf (']');
        return ip.Substring (1, right - 1);
    }
    int colon = ip.IndexOf (':');
    return colon == - 1 ? ip : ip.Substring (0, colon);
}

public class LinkedList
{
    public class Node
    {
        public int val;
        private Node next;

        public void SetNext(Node n) { next = n; }
        public Node GetNext() { return next; }
        public bool Equals(Node other) { return ReferenceEquals(this, other); }
    }

    private Node head;

    public Node Reverse(Node previous, Node current)
    {
        if (previous == null) return null;
        if (previous.Equals(head)) previous.SetNext(null);
        if (current == null)
        {
            head = previous;
            return head;
        }
        else
        {
            Node temp = current.GetNext();
            current.SetNext(previous);
            Reverse(current, temp);
        }
        return null;
    }
}

