public int Solution(int x, int[] a)
{
    int sum = 0;
    int searchedValue = x;
    int sumV = searchedValue * (searchedValue + 1) / 2;
    List<int> arrayList = new List<int>();
    for (int iii = 0; iii < a.Length; iii++)
    {
        if (a[iii] <= searchedValue && !arrayList.Contains(a[iii]))
        {
            sum += a[iii];
            if (sum == sumV) {
                return iii;
            }
            arrayList.Add(a[iii]);
        }
    }
    return -1;
}

