public static class MissingNumber
{
    public static int Solution(int x)
    {
        int sumV = x * (x + 1) / 2;
        List<int> seen = new List<int>();
        for (int divisor = 1; divisor < x; divisor++)
        {
            if (x % divisor == 0)
            {
                if (!seen.Contains(divisor))
                {
                    sumV -= divisor;
                    seen.Add(divisor);
                }
                if (divisor != x / divisor && !seen.Contains(x / divisor))
                {
                    sumV -= x / divisor;
                    seen.Add(x / divisor);
                }
            }
        }
        return sumV;
    }
}

