public static int[] Sort(int[] numbers, int digit) {
    if (numbers.Length == 0 || digit <= 0) return numbers;
    var space = new List<int>[10];
    for (int i = 0; i < 10; i++) space[i] = new List<int>();
    foreach (int num in numbers) {
        space[(num / digit) % 10].Add(num);
    }
    int k = 0;
    for (int i = 0; i < 10; i++) {
        int[] sortedBucket = Sort(space[i].ToArray(), digit / 10);
        foreach (int value in sortedBucket) {
            numbers[k++] = value;
        }
    }
    return numbers;
}

private static IEnumerable < T [] > EnumerateCombos < T > (IEnumerable < T > items, List < T > currentCombo, int startIndex, int threshold) {
    if (currentCombo.Count >= threshold) {
        yield break;
    }
    for (int i = startIndex; i < items.Count (); i ++) {
        var item = items.Skip (i).First ();
        currentCombo.Add (item);
        yield return currentCombo.ToArray ();
        foreach (var combo in EnumerateCombos (items, currentCombo, i + 1, threshold)) {
            yield return combo;
        }
        currentCombo.RemoveAt (currentCombo.Count - 1);
    }
}

public static int FindMIN(int[] A, int c) {
    int x = A[c];
    int position = c;
    while (c < A.Length) {
        if (x > A[c]) {
            x = A[c];
            position = c;
        }
        c++;
    }
    return position;
}

public static IEnumerable < IEnumerable < T > > GetPermutations < T > (IEnumerable < IEnumerable < T > > lists) {
    var pool = lists.Select (list => list.ToList ()).Where (list => list.Count > 0).ToList ();
    if (pool.Count == 0) {
        yield break;
    }
    var positions = new int [pool.Count];
    while (true) {
        yield return pool.Select ((list, idx) => list [positions [idx]]).ToList ();
        int carry = pool.Count - 1;
        while (carry >= 0) {
            positions [carry] ++;
            if (positions [carry] < pool [carry].Count) {
                break;
            }
            positions [carry] = 0;
            carry --;
        }
        if (carry < 0) {
            yield break;
        }
    }
}

