public int Solution(int X, int[] A) {
    HashSet<int> set = new HashSet<int>();
    int sum1 = 0, sum2 = 0;

    for (int i = 0; i <= X; i++) {
        sum1 += i;
    }

    for (int i = 0; i < A.Length; i++) {
        if (set.Contains(A[i])) {
            continue;
        }
        set.Add(A[i]);
        sum2 += A[i];

        if (sum1 == sum2) {
            return i;
        }
    }
    return -1;
}

