class Node {
    public Node Next;
}

class LinkedList {
    public Node Head;

    public Node Reverse(Node previous, Node current) {
        if (previous == null) return null;
        if (previous == Head) previous.Next = null;
        if (current == null) {
            Head = previous;
            return Head;
        } else {
            Node temp = current.Next;
            current.Next = previous;
            Reverse(current, temp);
        }
        return null;
    }
}

