public int [] ZeroFront(int [] nums) 
{
  if (nums == null) 
  {
    return null;
  }

  int [] result = new int[nums.Length];
  int zeroesPos = 0;
  int othersPos = result.Length - 1; 

  for (int i = 0; i < nums.Length; ++i) 
  {
    if (nums[i] == 0) 
    {
      result[zeroesPos] = 0;
      ++zeroesPos;
    } 
    else 
    {
      result[othersPos] = nums[i];
      --othersPos;
    } 
  }
  return result;
}

