        var index = value.Length - GetPartDivider();
        high = value.Substring(0, index);
        low = value.Substring(index);
    }

    var highName = GetHighProcessor().GetName(high); 
    var lowName = GetLowProcessor().GetName(low);

    if (highName != string.Empty)
    {
        buffer.Append(highName);
        buffer.Append(SEPARATOR);
        buffer.Append(GetToken());
        if (lowName != string.Empty)
        {
            buffer.Append(SEPARATOR);
        }
    }

    if (lowName != string.Empty)
    {
        buffer.Append(lowName);
    }

    return buffer.ToString();
}

protected override void CalculateBiQuadCoefficients () {
    double k = Math.Tan (Math.PI * Frequency / SampleRate);
    double denominator = 1 + k / Q + k * k;
    A0 = (1 + k * k) / denominator;
    A1 = 2 * (k * k - 1) / denominator;
    A2 = A0;
    B1 = A1;
    B2 = (1 - k / Q + k * k) / denominator;
}

