public static string CompressBad(string str) {
    int countConsecutive = 0;
    StringBuilder compressedString = new StringBuilder();
    for (int i = 0; i < str.Length; i++) {
        countConsecutive++;
        if (str.Length == i + 1) {
            compressedString.Append(str[i]).Append(countConsecutive);
            countConsecutive = 0;
