public void ActionPerformed(ActionEvent e) {
    long duration = System.currentTimeMillis() - startTime;
    float progress = (float) duration / (float) RUN_TIME;
    linePoint = new Point();
    linePoint.x = GetWidth() / 2;
    if (progress < 0.5f) {
        linePoint.y = (int) Math.Round(GetHeight() * (progress * 2));
    } else if (progress > 1f) {
        progress = 1f;
        ((Timer) e.Source).Stop();
        linePoint = null;
        ballPoint = null;
    } else {
        linePoint.y = (int) Math.Round(GetHeight() * (progress * 2));
        linePoint.y = GetHeight() - (linePoint.y - GetHeight());
        ballPoint.y = linePoint.y;
    }
    Repaint();
}

static Random random = new Random();

private static float GetRandomNumberBetween(float numberOne, float numberTwo) {
    if (numberOne == numberTwo) {
        throw new Exception("Both the numbers can not be equal");
    }
    float rand = (float)random.NextDouble();
    float highRange = Math.Max(numberOne, numberTwo);
    float lowRange = Math.Min(numberOne, numberTwo);
    float lowRand = (float)Math.Floor(rand - 1);
    float highRand = (float)Math.Ceiling(rand + 1);
    return (highRange - lowRange) * ((rand - lowRand) / (highRand - lowRand)) + lowRange;
}

