public class FilterCoefficients
{
    private double k;
    private double A0, A1, A2, B1, B2;

    public FilterCoefficients(double sampleRatio)
    {
        k = sampleRatio;
        double denom = k * k + k / Q + 1;
        A0 = k / (Q * denom);
        A2 = -A0;
        B1 = 2 * (k * k - 1) / denom;
        B2 = (k * k - k / Q + 1) / denom;
    }

    private const double Q = 1.0;
}

