        }
        foreach (string filePath in Directory.GetFiles(src, "*", SearchOption.AllDirectories))
        {
            File.Copy(filePath, filePath.Replace(src, dest), true);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine(ex);
    }
}

