public int Solution (int X, int[] A) {
    HashSet<int> emptyPositions = new HashSet<int> ();
    for (int i = 1; i <= X; i ++) {
        emptyPositions.Add (i);
    }
    for (int i = 0; i < A.Length; i ++) {
        emptyPositions.Remove (A [i]);
        if (emptyPositions.Count == 0) {
            return i;
        }
    }
    return - 1;
}

