public static class CoinCombinations
{
    public static int FindCombinationsCount(int amount, int[] coins, int checkFromIndex)
    {
        if (amount == 0) return 1;
        if (amount < 0 || coins.Length == checkFromIndex) return 0;
        int withFirstCoin = FindCombinationsCount(amount - coins[checkFromIndex], coins, checkFromIndex);
        int withoutFirstCoin = FindCombinationsCount(amount, coins, checkFromIndex + 1);
        return withFirstCoin + withoutFirstCoin;
    }
}

public static IEnumerable < T > TakeLast < T > (this IEnumerable < T > input, int count) {
    if (count <= 0)
        yield break;
    var inputList = input as IList < T >;
    if (inputList != null) {
        int start = Math.Max (0, inputList.Count - count);
        for (int index = start; index < inputList.Count; index ++) {
            yield return inputList [index];
        }
        yield break;
    }
    var recent = new Queue < T > ();
    foreach (T item in input) {
        if (recent.Count == count)
            recent.Dequeue ();
        recent.Enqueue (item);
    }
    while (recent.Count > 0) {
        yield return recent.Dequeue ();
    }
}

