private int[] RandNums(int total, int n) {
    var results = new int[n];
    if (total == 0) {
        return results;
    }
    var rs = new System.Numerics.BigInteger[n];
    var totalPlus1 = new System.Numerics.BigInteger(total + 1L);
    while (true) {
        for (int i = 0; i < n; ++i) {
            rs[i] = new System.Numerics.BigInteger(256, rand);
        }
        var sum = System.Numerics.BigInteger.Zero;
        foreach (var r in rs) {
            sum = sum.Add(r);
        }
        if (sum.CompareTo(System.Numerics.BigInteger.Zero) == 0) {
            continue;
        }
        for (int i = 0; i < n; ++i) {
            results[i] = (int) (sum.Mod(rs[i]).Mod(totalPlus1));
        }
        return results;
    }
}

public static DataTable GetWorksheetAsDataTable(ExcelWorksheet worksheet) {
    var dt = new DataTable(worksheet.Name);
    var dataColumns = GetDataColumns(worksheet).ToList();
    dt.Columns.AddRange(dataColumns.ToArray());
    int headerOffset = 1;
    int width = dt.Columns.Count;
    int depth = GetTableDepth(worksheet, headerOffset);
    int rowNum = 1;
    while (rowNum <= depth) {
        var row = dt.NewRow();
        int colNum = 1;
        while (colNum <= width) {
            object val = worksheet.Cells[rowNum + headerOffset, colNum].Value;
            row[colNum - 1] = val == null ? null : val.ToString();
            colNum++;
        }
        dt.Rows.Add(row);
        rowNum++;
    }
    return dt;
}

using System.Numerics;

public static int[] RandNums(int total, int n) {
    var results = new int[n];
    if (total == 0) {
        return results;
    }
    var rs = new BigInteger[n];
    var totalPlus1 = new BigInteger(total + 1L);
    while (true) {
        for (int i = 0; i < n; i++) {
            byte[] bytes = new byte[32];
            rand.NextBytes(bytes);
            bytes[31] &= 0x7F;
            rs[i] = new BigInteger(bytes);
        }
        var sum = BigInteger.Zero;
        foreach (var r in rs) {
            sum += r;
        }
        if (sum == BigInteger.Zero) {
            continue;
        }
        for (int i = 0; i < n; i++) {
            results[i] = (int) (sum % rs[i] % totalPlus1);
        }
        return results;
    }
}

