public static class EvenRemover
{
    public static void RemoveEven(int[] k, int n)
    {
        int counter = 0;
        for (int i = 0; i < n; i++)
        {
            if (k[i] % 2 == 1)
            {
                k[counter++] = k[i];
            }
        }
        while (counter < n)
        {
            k[counter++] = 0;
        }
    }
}

