public static int Solution(int x, int[] a) {
    int len = a.Length;
    if (x > len) {
        return -1;
    }
    int[] isFilled = new int[x];
    int jumped = 0;
    for (int i = 0; i < len; i++) {
        int v = a[i];
        if (v <= x) {
            if (isFilled[v - 1] == 0) {
                isFilled[v - 1] = 1;
                jumped += 1;
                if (jumped == x) {
                    return i;
                }
            }
        }
    }
    return -1;
}

public int Solution(int X, int[] A)
{
    var leaves = new HashSet<int>();
    for (int i = 0; i < A.Length; i++)
    {
        leaves.Add(A[i]);
        if (leaves.Contains(X) && leaves.Count == X) return i;
    }
    return -1;
}

