    {
        In.Seek(currentPos++, SeekOrigin.Begin);
        return In.ReadByte();
    }
    else if (currentPos > lastPosInFile && currentLineStart < currentLineEnd)
    {
        FindPrevLine();
        if (lastChar != '\n' && lastChar != '\r')
        {
            return '\n';
        }
        else
        {
            return Read();
        }
    }
    else if (currentPos < 0)
    {
        return -1;
    }
    else
    {
        FindPrevLine();
        return Read();
    }
}

