    int totalPlus1 = total + 1;
    while (true) {
        for (int i = 0;
        i < n; ++ i) {
            //Generate a random integer in between 0 and 256. 
            rs[i] = Random.Range(0,256);
        }
        int sum = 0;
        foreach (int r in rs){
            sum += r;
        }
        if (sum == 0) {
            continue;
