public static IEnumerable < IEnumerable < T > > GetPermutations < T > (IEnumerable < IEnumerable < T > > lists) {
    if (! lists.Any ()) {
        yield break;
    }
    List < IEnumerator < T > > iterators = new List < IEnumerator < T > > ();
    foreach (var list in lists) {
        var it = list.GetEnumerator ();
        if (! it.MoveNext ()) {
            continue;
        }
        iterators.Add (it);
    }
    bool done = false;
    while (! done) {
        yield return from it in iterators
            select it.Current;
        done = ! Advance < T > (iterators);
    }
}

private static bool Advance < T > (List < IEnumerator < T > > iterators) {
    var mainIt = iterators.GetEnumerator ();
    mainIt.MoveNext ();
    do {
        var subIt = mainIt.Current;
        if (! subIt.MoveNext ()) {
            subIt.Reset ();
            subIt.MoveNext ();
            if (! mainIt.MoveNext ()) {
                return false;
            }
        } else {
            return true;
        }
    } while (true);
}

public IDisposable Enter(string key) {
    Locker locker = ObtainLocker(key);
    locker.WaitCount++;
    locker.Enter();
    locker.WaitCount--;
    return locker;
}

private Locker ObtainLocker(string key) {
    Locker locker;
    lock (this.globalLock) {
        if (!this.locks.TryGetValue(key, out locker)) {
            this.locks[key] = locker = new Locker(this, key);
        }
    }
    return locker;
}

