using System.IO;

public static class ChunkReader
{
    public static byte[] ReadData(FileInfo f, int startByte, int chunkSize)
    {
        using (var raf = new FileStream(f.FullName, FileMode.Open, FileAccess.Read))
        {
            raf.Seek(startByte, SeekOrigin.Begin);
            byte[] data = new byte[chunkSize];
            int read = raf.Read(data, 0, chunkSize);
            if (read == data.Length)
            {
                return data;
            }
            byte[] trimmed = new byte[read];
            System.Array.Copy(data, trimmed, read);
            return trimmed;
        }
    }
}

public static int[] Sort(int[] numbers, int digit)
{
    if (numbers.Length == 0 || digit <= 0) return numbers;
    var buckets = new List<int>[10];
    for (int i = 0; i < 10; i++) buckets[i] = new List<int>();
    foreach (int num in numbers)
        buckets[(num / digit) % 10].Add(num);
    int k = 0;
    for (int i = 0; i < 10; i++)
    {
        int[] sorted = Sort(buckets[i].ToArray(), digit / 10);
        foreach (int value in sorted)
            numbers[k++] = value;
    }
    return numbers;
}

public int[] ZeroFront(int[] nums) {
    if (nums == null) {
        return null;
    }
    int[] result = new int[nums.Length];
    nums.CopyTo(result, 0);
    int zerosPos = 0;
    for (int i = 0; i < result.Length; i++) {
        if (result[i] == 0) {
            result[i] = result[zerosPos];
            result[zerosPos] = 0;
            zerosPos++;
        }
    }
    return result;
}

public static string Filter (string source, int start, int end, string dest, int dstart, int dend, int decimalDigits) {
    int dotPos = -1;
    int len = dest.Length;
    for (int i = 0; i < len; i++) {
        char c = dest [i];
        if (c == '.' || c == ',') {
            dotPos = i;
            break;
        }
    }
    if (dotPos >= 0) {
        if (source == "." || source == ",") {
            return "";
        }
        if (dend <= dotPos) {
            return null;
        }
        if (len - dotPos > decimalDigits) {
            return "";
        }
    }
    return null;
}

