public static class FrogRiver
{
    public static int Solution(int X, int[] A)
    {
        var seen = new HashSet<int>();
        int sum1 = 0;
        for (int v = 0; v <= X; v++) sum1 += v;
        int sum2 = 0;
        for (int i = 0; i < A.Length; i++)
        {
            if (seen.Contains(A[i])) continue;
            seen.Add(A[i]);
            sum2 += A[i];
            if (sum1 == sum2) return i;
        }
        return -1;
    }
}

