public class LinkedList
{
    public Node head;

    public Node reverse(Node previous, Node current)
    {
        if (previous == null) return null;
        if (previous == head) previous.setNext(null);
        if (current == null)
        {
            head = previous;
            return head;
        }
        Node temp = current.getNext();
        current.setNext(previous);
        reverse(current, temp);
        return null;
    }
}

static void Investigate(ParameterizedType p, params Type[] typeArgs)
{
    Class c = (Class)p.GetRawType();
    StringBuilder b = new StringBuilder(c.GetName());
    b.Append("<");
    Type[] localArgs = p.GetActualTypeArguments();
    if (typeArgs != null && typeArgs.Length > 0)
    {
        int i = 0;
        int nextTypeArg = 0;
        foreach (Type local in localArgs)
        {
            if (local is ParameterizedType)
            {
                ParameterizedType localP = (ParameterizedType)local;
                b.Append(localP.GetRawType()).Append("<");
                b.Append(typeArgs[nextTypeArg++]);
                b.Append(">");
            }
            else if (local is TypeVariable)
            {
                localArgs[nextTypeArg] = typeArgs[nextTypeArg];
                b.Append(localArgs[nextTypeArg]);
                nextTypeArg++;
            }
            else
            {
                b.Append(local.ToString());
            }
            b.Append(", ");
            i++;
        }
        if (typeArgs.Length > 0)
        {
            b.Remove(b.Length - 2, 2);
        }
        b.Append(">");
    }
    else
    {
        string args = string.Join(", ", localArgs);
        b.Append(args.Substring(1, args.Length - 2)).Append(">");
    }
    Console.WriteLine(b.ToString());
    Investigate(c, localArgs);
}

