public static class SingleNumberFinder
{
    public static int SingleNumber(int[] nums)
    {
        int answer = 0;
        List<int> al = new List<int>();
        foreach (int n in nums)
        {
            al.Add(n);
        }
        for (int i = 0; i < nums.Length; i++)
        {
            int test = nums[i];
            if (al.IndexOf(test) == al.LastIndexOf(test))
            {
                answer = nums[i];
