    }
}

public byte[] ReadData(FileInfo f, int startByte, int chunkSize) {
    using (var raf = new System.IO.FileStream (f.FullName, FileMode.Open, FileAccess.Read)) {
        raf.Seek (startByte, SeekOrigin.Begin);
        var data = new byte [chunkSize];
        int read = raf.Read (data, 0, data.Length);
        raf.Close ();
        if (read == data.Length) {
            return data;
        }
        else {
            return data.Take (read).ToArray ();
        }
    }
}

public IDisposable Enter (string key)
{
    Locker locker;
    lock (this.globalLock)
    {
        if (this.locks.ContainsKey (key))
        {
            locker = this.locks [key];
        }
        else
        {
            locker = new Locker (this, key);
            this.locks [key] = locker;
        }
        locker.WaitCount ++;
    }
    locker.Enter ();
    locker.WaitCount --;
    return locker;
}

