static boolean isImmutable (Object obj) {
    Class < ? > objClass = obj.getClass ();
    if (! Immutable.class.equals (objClass.getSuperclass ()) || ! Modifier.isFinal (objClass.getModifiers ())) {
        return false;
    }
    for (Field field : objClass.getDeclaredFields ()) {
        if (! Modifier.isFinal (field.getModifiers ()) || ! isValidFieldType (field.getType ())) {
            return false;
        }
    }
    return true;
}

public static byte [] readBytes (InputStream inputStream) throws IOException {
    byte [] buffer = new byte [32 * 1024];
    int bufferSize = 0;
    boolean eof = false;
    while (! eof) {
        int read = inputStream.read (buffer, bufferSize, buffer.length - bufferSize);
        if (read == - 1) {
            eof = true;
        } else {
            bufferSize += read;
            if (bufferSize == buffer.length) {
                buffer = growBuffer (buffer, bufferSize * 2);
            }
        }
    }
    return Arrays.copyOf (buffer, bufferSize);
}

private static byte [] growBuffer (byte [] oldBuffer, int newSize) {
    return Arrays.copyOf (oldBuffer, newSize);
}

