}

private static boolean hasTwoLaterMatches (int [] values, int index) {
    int counter = 0;
    for (int z = index + 1; z < values.length; z ++) {
        if (values [index] == values [z]) {
            counter ++;
            if (counter == 2) return true;
        }
    }
    return false;
}

