public static String join (String separator, String...values) {
    if (values.length == 0) return "";
    StringBuilder sb = new StringBuilder ();
    boolean first = true;
    for (String value : values) {
        String safe = (value == null) ? "" : value;
        if (! first) sb.append (separator);
        sb.append (safe);
        first = false;
    }
    return sb.toString ();
}

