long pow (long a, int b) {
    long result = 1;
    int exponent = b;
    long base = a;
    while (exponent > 1) {
        if (! isEven (exponent)) {
            result = result * base;
        }
        base = base * base;
        exponent = exponent / 2;
    }
    if (exponent == 1) {
        return result * base;
    }
    return result;
}

