public static boolean isPalindrome (String str) {
    String upper = str.toUpperCase ();
    int left = 0;
    int right = upper.length () - 1;
    while (left < right) {
        if (! upper.substring (left, left + 1).equalsIgnoreCase (upper.substring (right, right + 1))) {
            return false;
        }
        left ++;
        right --;
    }
    return true;
}

