def binary_search(L, x):
    lo, hi = 0, len(L) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if L[mid] < x:
            lo = mid + 1
        elif L[mid] > x:
            hi = mid - 1
        else:
            while mid > 0 and L[mid - 1] == x:
                mid -= 1
            return mid
    return -1

