class LinkedList:
    def __init__(self):
        self.first = None
        self.count = 0

    def size(self):
        return self.count

    def second_max_key(self):
        if self.size() < 2:
            return None
        maximum = None
        max_2 = None
        second = self.first.next
        if self.first.key > second.key:
            maximum = self.first
            max_2 = second
        else:
            maximum = second
            max_2 = self.first
        x = second.next
        while x is not None:
            if x.key > maximum.key:
                max_2 = maximum
                maximum = x
            elif x.key > max_2.key and x.key < maximum.key:
                max_2 = x
            x = x.next
        return max_2.key

