def sort(numbers, digit):
    if len(numbers) == 0 or digit <= 0:
        return numbers
    space = [[] for _ in range(10)]
    for value in numbers:
        bucket_index = (value // digit) % 10
        space[bucket_index].append(value)
    result = []
    for bucket in space:
        result.extend(sort(bucket, digit // 10))
    return result

