def all_pairs(lst):
    pairs = []
    n = len(lst)
    if n == 0:
        return [()]
    if n == 1:
        return [tuple(lst)]
    pad = None
    if n % 2 != 0:
        for candidate in (None, True):
            if candidate not in lst:
                pad = candidate
                break
        if pad is None:
            code = 0
            while chr(code) in lst:
                code += 1
            pad = chr(code)
        lst.append(pad)
        n += 1
    for i in range(1, n):
        pair = (lst[0], lst[i])
        rest = lst[1:i] + lst[i + 1:]
        for tail in all_pairs(rest):
            group = [pair] + tail
            if pad is not None:
                for j, tu in enumerate(group):
                    if pad in tu:
                        group[j] = (tu[0],)
                        break
            pairs.append(group)
    return pairs

