def get_name(value):
    negative = value.startswith("-")
    if negative:
        value = value[1:]
    decimals = value.find(".")
    decimal_value = None
    if decimals >= 0:
        decimal_value = value[decimals + 1:]
        value = value[:decimals]
    name = processor.get_name(value)
    if not name:
        name = ZERO_TOKEN
    elif negative:
        name = MINUS + SEPARATOR + name
    if decimal_value:
        name = SEPARATOR.join([
            name,
            UNION_AND,
            processor.get_name(decimal_value),
            SCALE.get_name(-len(decimal_value)),
        ])
    return name

