def rand_nums(total, n):
    results = [0] * n
    if total == 0:
        return results
    total_plus_1 = total + 1
    while True:
        rs = [random.getrandbits(256) for _ in range(n)]
        s = sum(rs)
        if s == 0:
            continue
        for i in range(n):
            results[i] = (s % rs[i]) % total_plus_1
        return results

