def sort(numbers, digit):
    if len(numbers) == 0 or digit <= 0:
        return numbers
    space = [[] for _ in range(10)]
    for number in numbers:
        i = (number // digit) % 10
        space[i] = put_in_bucket(space[i], number)
    result = []
    for i in range(10):
        result.extend(sort(space[i], digit // 10))
    return result

