def is_balanced(s):
    result = False
    if len(s) < 2:
        return False
    stack = []
    for ch in s:
        if ch not in PARENTHESES_MAP_RIGHT and ch not in PARENTHESES_MAP_LEFT:
            continue
        if ch in PARENTHESES_MAP_LEFT:
            stack.append(ch)
        else:
            if stack and stack.pop() == PARENTHESES_MAP_RIGHT[ch]:
                result = True
            else:
                return False
    if stack:
        return False
    return result

