def decrypt(s):
    crypt = []
    groups = s.split("#")
    for i, group in enumerate(groups):
        j = 0
        if i == len(groups) - 1 and not s.endswith("#"):
            j = len(group)
        if len(group) > 2:
            j = len(group) - 2
        for k in range(j):
            crypt.append(int(group[k:k + 1]))
        if j < len(group):
            crypt.append(int(group[j:]))
    result = []
    for c in crypt:
        result.append(chr((ord("a") + c) - 1))
    return "".join(result)

