def all_pairs(lst):
    pairs = []
    if not lst:
        pairs.append(tuple())
    elif len(lst) == 1:
        pairs.append(tuple(lst))
    elif len(lst) == 2:
        pairs.append(tuple(lst))
    else:
        if len(lst) % 2 != 0:
            for i in (None, True):
                if i not in lst:
                    lst.append(i)
                    PAD = i
                    break
            else:
                while chr(i) in lst:
                    i += 1
                PAD = chr(i)
                lst.append(PAD)
        else:
            PAD = False
        a = lst[0]
        for i in range(1, len(lst)):
            pair = (a, lst[i])
            rest_list = lst[1:i] + lst[i + 1 :]
            for rest in all_pairs(rest_list):
                pairs_list = [pair] + rest
                if PAD is not False:
