def sort(numbers, digit):
    if len(numbers) == 0 or digit <= 0:
        return numbers
    buckets = [[] for _ in range(10)]
    for num in numbers:
        buckets[(num // digit) % 10].append(num)
    k = 0
    for i in range(10):
        for value in sort(buckets[i], digit // 10):
            numbers[k] = value
            k += 1
    return numbers

