def getName(value):
    negative = value.startswith("-")
    if negative:
        value = value[1:]
    decimals = value.find(".")
    decimalValue = None
    if decimals >= 0:
        decimalValue = value[decimals + 1:]
        value = value[:decimals]
    name = processor.getName(value)
    if not name:
        name = ZERO_TOKEN
    elif negative:
        name = MINUS + SEPARATOR + name
    if decimalValue:
        name = (name + SEPARATOR + UNION_AND + SEPARATOR +
                processor.getName(decimalValue) + SEPARATOR +
                SCALE.getName(-len(decimalValue)))
    return name

def find_min(A, c):
    x = A[c]
    position = c
    while c < len(A):
        if x > A[c]:
            x = A[c]
            position = c
        c += 1
    return position

