def json_scan(json_obj, key):
    result = None
    for element in json_obj:
        if str(element) == key:
            result = json_obj[element]
        else:
            value = json_obj[element]
            if type(value) == DictType:
                result = json_scan(value, key)
            elif type(value) == ListType:
                result = json_scan(element, key)
    return result

