class LinkedList:
    def __init__(self):
        self.head = None

    def reverse(self, previous, current):
        if previous is None:
            return None
        if previous is self.head:
            previous.next = None
        if current is None:
            self.head = previous
            return self.head
        temp = current.next
        current.next = previous
        self.reverse(current, temp)
        return None

