import os
import shutil

def copyFolder(src, dest):
    try:
        for root, dirs, files in os.walk(src):
            relative = os.path.relpath(root, src)
            target = dest if relative == "." else os.path.join(dest, relative)
            if not os.path.isdir(target):
                os.makedirs(target)
            for name in files:
                shutil.copy2(os.path.join(root, name), os.path.join(target, name))
    except Exception as ex:
        print(ex)

def solution(s, p, q):
    character_mapping = {'A': 1, 'C': 2, 'G': 3, 'T': 4}
    integer_input = [character_mapping[c] for c in s]
    result = [0] * len(p)
    for index in range(len(p)):
        if p[index] == q[index]:
            result[index] = integer_input[p[index]]
            break
        sub_array = integer_input[p[index]:q[index] + 1]
        result[index] = min(sub_array)
    return result

def decrypt(s):
    crypt = []
    groups = s.split("#")
    last_index = len(groups) - 1
    for i, group in enumerate(groups):
        j = 0
        if i == last_index and not s.endswith("#"):
            j = len(group)
        if len(group) > 2:
            j = len(group) - 2
        for k in range(j):
            crypt.append(int(group[k:k + 1]))
        if j < len(group):
            crypt.append(int(group[j:]))
    return "".join(chr(ord("a") + c - 1) for c in crypt)

