class LinkedList:
    def __init__(self):
        self.head = None

    def reverse(self, previous, current):
        if previous is None:
            return None
        if previous is self.head:
            previous.next = None
        if current is None:
            self.head = previous
            return self.head
        else:
            temp = current.next
            current.next = previous
            self.reverse(current, temp)
        return None

class ReverseLineReader:
    def __init__(self, filename):
        self.filename = filename
        self.currentPos = None
        self.currentLineEnd = None

    def findPrevLine(self):
        pass

    def read(self):
        with open(self.filename, "rb") as fh:
            if self.currentLineEnd is None:
                fh.seek(0, 2)
                self.currentLineEnd = fh.tell()
            if self.currentPos is None:
                self.currentPos = self.currentLineEnd
            start = max(self.currentPos - 1, 0)
            fh.seek(start)
            chunk = fh.read(self.currentPos - start)
            self.currentPos = start
            if not chunk:
                return ""
            return chunk.decode("utf-8")[::-1]

