def binary_search(L, x):
	lo = 0
	hi = len(L) - 1
	while lo <= hi:
		mid = (lo + hi) // 2
		if L[mid] < x:
			lo = mid + 1
		elif L[mid] > x:
			hi = mid - 1
		else:
			return mid
	return -1

