ZERO_TOKEN = "zero"
MINUS = "minus"
SEPARATOR = " "
UNION_AND = "and"


class NumberNamer:
    def __init__(self, processor, scale):
        self.processor = processor
        self.scale = scale

    def get_name(self, value):
        negative = value.startswith("-")
        if negative:
            value = value[1:]
        decimals = value.find(".")
        decimal_value = None
        if decimals >= 0:
            decimal_value = value[decimals + 1:]
            value = value[:decimals]
        name = self.processor.get_name(value)
        if not name:
            name = ZERO_TOKEN
        elif negative:
            name = MINUS + SEPARATOR + name
        if decimal_value:
            name = (name + SEPARATOR + UNION_AND + SEPARATOR
                    + self.processor.get_name(decimal_value) + SEPARATOR
                    + self.scale.get_name(-len(decimal_value)))
        return name

def zero_front(nums):
    if nums is None:
        return None
    result = [0] * len(nums)
    zeros_pos = 0
    for value in nums:
        if value == 0:
            result[zeros_pos] = 0
            zeros_pos += 1
    fill = len(nums) - 1
    for value in reversed(nums):
        if value != 0:
            result[fill] = value
            fill -= 1
    return result

import random

def rand_nums(self, total, n):
    results = [0] * n
    if total == 0:
        return results
    while True:
        rs = [random.getrandbits(256) for _ in range(n)]
        s = sum(rs)
        if s == 0:
            continue
        for i in range(n):
            results[i] = (s % rs[i]) % (total + 1)
        return results

