parentheses_map_left = {"(": ")"}
parentheses_map_right = {")": "("}


def is_balanced(s):
    result = False
    if len(s) < 2:
        return False
    stack = []
    for ch in s:
        if ch not in parentheses_map_right and ch not in parentheses_map_left:
            continue
        if ch in parentheses_map_left:
            stack.append(ch)
        else:
            if stack and stack.pop() == parentheses_map_right[ch]:
                result = True
            else:
                return False
    if stack:
        return False
    return result

