def all_pairs(lst):
    if not lst:
        return [tuple()]
    if len(lst) <= 2:
        return [tuple(lst)]
    pairs = []
    pad, lst = _with_pad(lst)
    first = lst[0]
    for i in range(1, len(lst)):
        pair = (first, lst[i])
        rest_list = lst[1:i] + lst[i + 1:]
        for rest in all_pairs(rest_list):
            entry = [pair] + rest
            pairs.append(_collapse_pad(entry, pad))
    return pairs

def _with_pad(lst):
    if len(lst) % 2 == 0:
        return False, lst
    for i in (None, True):
        if i not in lst:
            lst.append(i)
            return i, lst
    i = 0
    while chr(i) in lst:
        i += 1
    pad = chr(i)
    lst.append(pad)
    return pad, lst

def _collapse_pad(entry, pad):
    if pad is not False:
        for j, tu in enumerate(entry):
            if pad in tu:
                entry[j] = (tu[0],)
                break
    return entry

