def solution(S, P, Q):
    answer = [0] * len(P)
    chars = list(S)
    cumulative_answers = [[0] * (len(chars) + 1) for _ in range(4)]
    for iii in range(len(chars)):
        if iii > 0:
            for zzz in range(4):
                cumulative_answers[zzz][iii + 1] = cumulative_answers[zzz][iii]
        if chars[iii] == 'A':
            cumulative_answers[0][iii + 1] += 1
        elif chars[iii] == 'C':
            cumulative_answers[1][iii + 1] += 1
        elif chars[iii] == 'G':
            cumulative_answers[2][iii + 1] += 1
        elif chars[iii] == 'T':
            cumulative_answers[3][iii + 1] += 1
    for iii in range(len(P)):
        for zzz in range(4):
            if cumulative_answers[zzz][Q[iii] + 1] - cumulative_answers[zzz][P[iii]] > 0:
                answer[iii] = zzz + 1
                break
    return answer

def roundrobin(* iterables):
	iter_items = []
	timers = [iter(it) for it in iterables]
	while timers:
		exhausted = []
		for it in timers:
			try:
				data = next(it)
			except StopIteration:
				exhausted.append(it)
				continue
			iter_items.append(data)
			yield data
		for gone in exhausted:
			timers.remove(gone)

